function installIconGlyphs(root=document.body){if(!root)return;root.querySelectorAll?.('button[data-action="ask-accountant"]:not(.ask-accountant-icon)').forEach(button=>{button.classList.add('ask-accountant-icon');button.setAttribute('aria-label','Preguntar o asignar tarea');button.title='Preguntar o asignar tarea';button.innerHTML=questionIcon});const chars=Object.keys(glyphSvgs).sort((a,b)=>b.length-a.length),walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walk.nextNode())if(walk.currentNode.parentElement&&!walk.currentNode.parentElement.closest('svg,script,style,textarea,input,code'))nodes.push(walk.currentNode);for(const node of nodes){if(!chars.some(ch=>node.nodeValue.includes(ch)))continue;const frag=document.createDocumentFragment(),parts=node.nodeValue.split(new RegExp(`(${chars.map(ch=>ch.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')})`,'g'));for(const part of parts){if(glyphSvgs[part]){const span=document.createElement('span');span.className='text-icon';span.setAttribute('aria-hidden','true');span.innerHTML=`<svg viewBox="0 0 24 24">${glyphSvgs[part]}</svg>`;frag.append(span)}else if(part)frag.append(document.createTextNode(part));}node.replaceWith(frag)}}
