function guideBlock(){const id=state.view,prefs=userPrefs(),copy=guideCopy[id];if(!copy||prefs.guideHidden.includes(id))return '';return `<section class="module-guide" id="module-guide"><button class="guide-close" data-action="guide-close" aria-label="Cerrar guía">×</button>${[['PARA QUÉ SIRVE',copy[0]],['CÓMO FUNCIONA',copy[1]],['HASTA DÓNDE PUEDE LLEGAR',copy[2]]].map(([label,text])=>`<div><small>${label}</small><p>${esc(text)}</p></div>`).join('')}<div class="guide-try"><small>PRUÉBALO</small><ol>${copy[3].map((step,i)=>`<li><span>${i+1}</span><button type="button" data-action="guide-step" data-step="${i}">${esc(step)}</button></li>`).join('')}<li><span>+</span><span>Prueba el ícono ${questionIcon} junto a un dato para preguntar o asignar una tarea.</span></li></ol></div></section>`}
