function questionModal(data){const ownerInfo=questionOwner(data.module,data.name),recipient=allProfiles().find(p=>p.id===ownerInfo.id)||allProfiles()[0],wa=(state.personalAgents?.[recipient.id]||defaultAgent(recipient)).channel.includes('WhatsApp');const question= data.extra==='zona'?`${recipient.name}, ${data.name.replace('Zona · ','')} va en ${data.value.split(' · ')[0]}. Esperaba más. ¿Qué pasó?`:`${recipient.name}, tengo una consulta sobre ${data.name}: ${data.value}. ¿Me ayudas a revisarlo?`,context=`${data.name.replace('Zona · ','')} · ${data.value} · ${data.period}`;openModal('Preguntar por este dato',`<nav class="question-action-tabs"><button class="active" data-action="question-task-tab" data-tab="question">Pregunta</button><button data-action="question-task-tab" data-tab="task">Tarea</button></nav><form id="ask-data-form" class="ask-data-form"><article class="asked-data-card"><span class="kicker">${esc(moduleNames[data.module]||'MOVIADS Central')}</span><strong>${esc(data.name.replace('Zona · ',''))}</strong><p>${esc(data.value)} · ${esc(data.period)}</p></article><label class="field-label">PARA<select name="to">${allProfiles().map(p=>`<option value="${p.id}" ${p.id===recipient.id?'selected':''}>${esc(p.name)}${p.name===p.role?'':' · '+esc(p.role)}</option>`).join('')}</select></label><p class="suggestion-reason" data-owner-reason="${esc(ownerInfo.id)}">${esc(ownerInfo.reason)}</p><label class="field-label">TU PREGUNTA<textarea name="body" required>${esc(question)}</textarea></label><label class="whatsapp-choice"><input name="whatsapp" type="checkbox" ${wa?'checked':''}><span>Avisar también por WhatsApp</span><small>${wa?'Según la preferencia de avisos de '+esc(recipient.name):'Este perfil tiene avisos por correo'}</small></label><input type="hidden" name="module" value="${esc(data.module)}"><input type="hidden" name="name" value="${esc(data.name)}"><input type="hidden" name="value" value="${esc(data.value)}"><input type="hidden" name="period" value="${esc(data.period)}"><input type="hidden" name="target" value="${esc(data.target||data.module)}"><div class="form-submit"><button class="button primary">Enviar pregunta</button></div></form><form id="context-task-form" class="task-form" hidden><article class="asked-data-card"><span class="kicker">DATO VINCULADO</span><strong>${esc(data.name.replace('Zona · ',''))}</strong><p>${esc(data.value)} · ${esc(data.period)}</p></article><label class="field-label">QUÉ HAY QUE HACER<input name="title" value="Revisar ${esc(data.name.replace('Zona · ',''))}" required></label><label class="field-label">RESPONSABLE<select name="to">${allProfiles().map(p=>`<option value="${p.id}" ${p.id===recipient.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="task-fields"><label class="field-label">FECHA LÍMITE<input name="due" type="date" value="2026-11-20" required></label><label class="field-label">PRIORIDAD<select name="priority"><option>Normal</option><option>Alta</option><option>Urgente</option></select></label></div><input type="hidden" name="context" value="${esc(context)}"><button class="button primary">Asignar tarea</button></form>`)}
function agentPreview(a){const found=a.clients.includes('Clínica Sonrisa'),level=autonomyLevels.indexOf(a.autonomy),ask=found||level<3,channel=a.channel==='WhatsApp y correo'?'WhatsApp + correo':a.channel.includes('WhatsApp')?'WhatsApp':'correo';if(!agentCanWriteNow(a))return `<div class="agent-preview-top"><span class="preview-dot"></span><span>VISTA PREVIA EN VIVO</span></div><div class="preview-message"><small>${channel} · Clínica Sonrisa</small><p>Encontré a Clínica Sonrisa en Obarrio.</p><p>${esc(a.name)} esperará hasta las ${esc(a.start)} para escribir.</p></div><small class="preview-guard">Horario permitido: ${esc(a.start)} a ${esc(a.end)} · resumen a las ${esc(a.summary)}</small>`;return `<div class="agent-preview-top"><span class="preview-dot"></span><span>VISTA PREVIA EN VIVO</span></div><div class="preview-message"><small>${channel==='WhatsApp'?'WhatsApp':'Correo'} · Clínica Sonrisa</small><p>Encontré a Clínica Sonrisa en Obarrio. Tiene dos sedes y busca campañas con QR.</p>${ask?`<p>${esc(a.name)}: ¿Quieres que le escriba para compartir una propuesta?</p><div class="preview-actions"><button type="button">Sí</button><button type="button">No</button></div>`:`<p>${esc(a.name)}: Le escribí a las 9:02, te aviso si responde.</p>`}</div><small class="preview-guard">${found?'Cliente marcado: este contacto siempre requiere tu permiso.':`Hasta ${a.maxPerLead} mensajes por lead al día · ${a.followup} seguimientos.`}</small>`}
function refreshAgentPreview(){const a=agentConfig(),host=$('#agent-preview');if(host)host.innerHTML=agentPreview(a);const title=$('.agent-name-input');if(title&&title.value!==a.name)title.value=a.name;const level=$('.control-title span');if(level)level.textContent=a.autonomy;const intensity=$('.control-card strong');if(intensity)intensity.textContent=['Suave','Tranquila','Moderada','Activa','Agresiva'][a.intensity-1]||'Suave';const limits=$$('.control-card small');if(limits[0])limits[0].textContent=`${a.maxPerLead} mensajes por lead al día · ${a.followup} seguimientos`;}
function personalAgent(){const a=agentConfig(),p=profile(),maxLevel=p.access==='owner'?4:p.access==='sales'?3:2,activeLevel=Math.min(maxLevel,Math.max(0,autonomyLevels.indexOf(a.autonomy)));return `<section class="personal-agent-layout"><div class="agent-settings"><header><span class="kicker">TU FORMA DE TRABAJAR</span><input class="agent-name-input" data-agent-field="name" aria-label="Nombre del agente" value="${esc(a.name)}"><p>${a.autonomy==='Autónomo'?'Actúa y te mantiene al tanto.':a.autonomy==='Consultar con mis clientes'?'Te consulta antes de escribir a tus clientes.':`Trabaja en modo ${esc(a.autonomy.toLowerCase())} y sigue tus reglas.`}</p></header><label class="control-title">Autonomía <span>${esc(a.autonomy)}</span></label><div class="autonomy-slider"><input type="range" min="0" max="${maxLevel}" step="1" value="${activeLevel}" data-agent-field="autonomy" aria-label="Autonomía"><div>${autonomyLevels.slice(0,maxLevel+1).map(x=>`<small>${x}</small>`).join('')}</div></div><div class="agent-control-grid"><label class="control-card"><span>Intensidad</span><strong>${['Suave','Tranquila','Moderada','Activa','Agresiva'][a.intensity-1]||'Suave'}</strong><input type="range" min="1" max="5" value="${a.intensity}" data-agent-field="intensity" aria-label="Intensidad"><small>${a.maxPerLead} mensajes por lead al día · ${a.followup} seguimientos</small></label><label class="control-card"><span>Canal de aviso</span><select data-agent-field="channel"><option ${a.channel==='WhatsApp'?'selected':''}>WhatsApp</option><option ${a.channel==='Correo'?'selected':''}>Correo</option><option ${a.channel==='WhatsApp y correo'?'selected':''}>WhatsApp y correo</option></select></label><label class="control-card"><span>Horario para escribir</span><div class="time-range"><input type="time" data-agent-field="start" value="${a.start}"><input type="time" data-agent-field="end" value="${a.end}"></div></label><label class="control-card"><span>Resumen diario</span><input type="time" data-agent-field="summary" value="${a.summary}"></label><label class="control-card"><span>Tono de los mensajes</span><select data-agent-field="tone">${['Formal','Cercano','Directo'].map(x=>`<option ${x===a.tone?'selected':''}>${x}</option>`).join('')}</select></label><div class="control-card client-control"><span>Mis clientes <small>Siempre requieren tu permiso</small></span><div class="client-chips">${['Tropigas','McDonald’s','Clínica Sonrisa','Cochez'].map(x=>`<label><input type="checkbox" data-agent-client="${esc(x)}" ${a.clients.includes(x)?'checked':''}>${esc(x)}</label>`).join('')}</div></div></div></div><aside class="agent-preview" id="agent-preview">${agentPreview(a)}</aside></section>`}
function customizePanel(){const pref=userPrefs(),items=[['renewals','Clientes por renovar'],['hot-leads','Leads calientes'],['network','Estado de la red'],['inventory','Inventario disponible']];openModal('Personalizar mi pantalla',`<section class="customize-section"><span class="kicker">INICIO</span><p>Elige las tarjetas y ajusta su orden.</p>${pref.homeOrder.map((id,i)=>{const label=items.find(x=>x[0]===id)?.[1]||id;return `<div class="customize-row"><label><input type="checkbox" data-pref-toggle="${id}" ${pref.homeCards.includes(id)?'checked':''}>${label}</label><span><button data-action="pref-move" data-id="${id}" data-dir="-1" ${i===0?'disabled':''}>↑</button><button data-action="pref-move" data-id="${id}" data-dir="1" ${i===pref.homeOrder.length-1?'disabled':''}>↓</button></span></div>`}).join('')}</section><section class="customize-section"><span class="kicker">FAVORITOS</span><p>Fija módulos arriba del menú.</p><div class="favorite-options">${navList().filter(x=>!['inicio','mi-agente'].includes(x[0])).map(([id,label])=>`<label><input type="checkbox" data-pref-favorite="${id}" ${pref.favorites.includes(id)?'checked':''}>${esc(label)}</label>`).join('')}</div></section><section class="customize-section"><span class="kicker">ACENTO</span><div class="accent-options">${[['teal','Turquesa'],['sky','Cielo'],['indigo','Índigo'],['coral','Coral']].map(([id,label])=>`<button class="accent-swatch ${pref.accent===id?'selected':''}" data-action="pref-accent" data-id="${id}" aria-label="${label}"><i class="accent-${id}"></i>${label}</button>`).join('')}</div></section><section class="customize-section"><span class="kicker">DENSIDAD</span><div class="density-options"><button data-action="pref-density" data-id="comfortable" class="${pref.density==='comfortable'?'selected':''}">Cómoda</button><button data-action="pref-density" data-id="compact" class="${pref.density==='compact'?'selected':''}">Compacta</button></div></section>`,true)}
function brainForView(){const item=brainAreas[brainViewKey()];if(!item)return '';const val=x=>typeof x==='function'?x():x;const restricted=profile().access==='service',canApproveThis=canApprove()||(profile().access==='finance'&&state.view==='finanzas');const amount=restricted?0:item.amount;const id=`brain-${state.view}`,approved=state.decisions[id]==='Aprobada',collapsed=Boolean(state.brainCollapsed?.[id]);return `<section class="brain-card ${approved?'is-approved':''} ${collapsed?'is-collapsed':''}" data-brain="${id}" ${item.highlight?`data-highlight="${esc(Object.entries(ensureMonth('2026-12')).filter(([unit,row])=>['Obarrio','Calle 50'].includes(FLEET[Number(unit.slice(-2))-1]?.zone)&&row.some(x=>!x)).map(([unit])=>unit).join(','))}"`:''}><header class="brain-head"><div><span class="brain-status"><i></i>${approved?'Recomendación aprobada':'Aprendiendo de la red'}</span><h2>Cerebro de ${item.area}</h2><p>Basado en 4 semanas de datos de la red</p></div><button class="brain-collapse" data-action="brain-collapse" data-id="${id}" aria-expanded="${!collapsed}">${collapsed?'Expandir':'Contraer'}</button></header><div class="brain-body"><div class="brain-steps"><article><small>ANALIZA</small><p>${esc(val(item.seen))}</p></article><article><small>INTERPRETA</small><p>${esc(val(item.why))}</p></article><article><small>PREDICE</small><p>${esc(restricted&&state.view==='clientes'?'La renovación está próxima; el período actual termina el 30 de noviembre.':val(item.predict))}</p><b>${esc(item.confidence)} confianza</b></article><article><small>RECOMIENDA</small><p>${esc(val(item.recommend))}</p></article></div><footer class="brain-footer"><strong>${amount?`+${money(amount)} ${state.view==='finanzas'?'en saldos a gestionar':state.view==='clientes'?'en renovación por proteger':'de oportunidad'}`:'Impacto por medir'}</strong><div>${approved?'<span class="brain-approved-label">Aprobado · agregado a actividad de agentes</span>':canApproveThis?`<button class="button primary small" data-action="brain-approve" data-id="${id}" data-area="${esc(item.area)}" data-text="${esc(val(item.recommend))}">Aprobar</button>`:'<span class="quiet-note">Requiere perfil con permiso de aprobación</span>'}<button class="button quiet small" data-action="brain-detail" data-id="${id}" data-area="${esc(item.area)}" data-text="${esc(val(item.recommend))}">Ver detalle</button></div></footer></div></section>`}
function brainOverview(){const restricted=profile().access==='service',showFinance=owner()||profile().access==='finance';const rows=Object.entries(brainAreas).filter(([key])=>key!=='centro-agentes'&&(showFinance||key!=='finanzas')&&state.decisions?.[`brain-${key}`]!=='Aprobada').map(([key,item])=>({key,item,amount:restricted?0:Number(item.amount)||0}));const total=rows.reduce((n,x)=>n+x.amount,0);return `<section class="brain-overview"><header><div><span class="brain-status"><i></i>Aprendiendo de la red</span><h2>${restricted?'Acciones para revisar hoy':`Hoy hay ${money(total)} sobre la mesa`}</h2><p>Recomendaciones abiertas de los cerebros por área · Basado en 4 semanas de datos de la red</p></div></header><div class="brain-overview-list">${rows.filter(x=>restricted||x.amount>0).map(({key,item,amount})=>`<article class="brain-summary-row"><button data-view="${key}"><span><b>Cerebro de ${item.area}</b><small>${esc(typeof item.recommend==='function'?item.recommend():item.recommend)}</small></span>${restricted?'':`<strong>${money(amount)} <i>↗</i></strong>`}</button></article>`).join('')}</div><div class="brain-overview-foot">${restricted?'Las recomendaciones usan actividad y cobertura; los datos del módulo Finanzas requieren un perfil autorizado.':'Las cifras reúnen presupuestos, renovaciones y saldos registrados, sin sumar ventas estimadas de rutas.'}</div></section>`}

function viewContent(){switch(state.view){case'inicio':return home();case'mi-agente':return personalAgent();case'mapa-vivo':return liveMap();case'centro-agentes':return agentCenter();case'inventario':return inventory();case'programacion':return scheduling();case'clientes':return clients();case'medicion':return measurement();case'agentes':return agents();case'flota':return fleet();case'finanzas':return finance();case'mensajes':return messages();case'equipo':return team();case'conexiones':return connections();default:return home()}}
function onAirScreen(id){const loopBrands=[...CLIENTS.filter(c=>c.stage==='Activo').map(c=>c.name),'Bambito'];return `<section class="onair-wrap" data-onair="${id}"><div class="onair-heading"><span class="live-chip"><i></i> AL AIRE AHORA</span><span>18 pantallas · loop de 8 posiciones</span></div><div class="led-frame"><div class="led-content" data-led-content><strong style="color:#15A595">TROPIGAS</strong><span class="led-message">${esc(CLIENTS[0].campaign)}</span><small>Presente donde tu día te lleva.</small></div><div class="led-glare"></div></div><div class="loop-track">${Array.from({length:8},(_,i)=>`<span class="loop-slot ${i===0?'current':''}" data-loop-slot="${i}"><i>${String(i+1).padStart(2,'0')}</i>${esc(loopBrands[i%loopBrands.length])}</span>`).join('')}</div><div class="loop-progress"><i data-loop-progress></i></div><div class="onair-foot"><span>Reproducciones de hoy</span><strong data-onair-plays>${num(livePlays)}</strong><span class="onair-zone">Ciudad de Panamá · Red MOVIADS</span></div></section>`}
function startOnAir(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;let ix=0;const colors={Tropigas:'#15A595','McDonald’s':'#F7B318',Novey:'#E66B45','Denago EV':'#6E9BD8',Cochez:'#E06D4D',Wheelz:'#8668D8','Nexa Solutions':'#45BBD3',Bambito:'#D9A65C'};const brands=[...CLIENTS.filter(c=>c.stage==='Activo').map(c=>[c.name.toUpperCase(),c.campaign||c.name,'Publicidad móvil por Ciudad de Panamá.',colors[c.name]||'#15A595']),['BAMBITO','Crecer juntos','Presencia para tu negocio.',colors.Bambito]];const rotate=()=>{if(document.hidden)return;ix=(ix+1)%brands.length;const [name,msg,sub,color]=brands[ix];document.querySelectorAll('[data-led-content]').forEach(el=>{el.classList.add('led-change');setTimeout(()=>{el.innerHTML=`<strong style="color:${color}">${esc(name)}</strong><span class="led-message">${esc(msg)}</span><small>${esc(sub)}</small>`;el.classList.remove('led-change')},350)});document.querySelectorAll('[data-loop-slot]').forEach((el,i)=>el.classList.toggle('current',i===ix));livePlays+=144;document.querySelectorAll('[data-onair-plays]').forEach(el=>el.textContent=num(livePlays));};liveIntervals.push(setInterval(rotate,10000));}
