function startAgentSimulation(approved=false){const box=$('#agent-live');if(!box)return;if(!agentCanWriteNow()){const messages=box.querySelector('.live-chat-messages');if(messages)messages.innerHTML='<p class="chat-start">Fuera del horario para escribir</p><div class="live-chat-row">El agente esperará al horario configurado.</div>';return;}if((!isAutonomous()||agentConfig().clients.includes('Clínica Sonrisa'))&&!approved){const messages=box.querySelector('.live-chat-messages');if(messages)messages.innerHTML='<p class="chat-start">Esperando aprobación antes de escribir</p><div class="live-chat-row">El agente preparó el contacto y espera tu respuesta.</div><div class="preview-actions"><button data-action="agent-contact-yes">Sí, escribir</button><button data-action="agent-contact-no">No, omitir</button></div>';const badge=box.querySelector('.live-chip');if(badge)badge.innerHTML='<i></i> pendiente de aprobación';return;}state.leadHeat.l1='Tibio';if(!agentActivityTimer)agentActivityTimer=setInterval(()=>{if(document.hidden||state.view!=='agentes'&&state.view!=='centro-agentes')return;const log=box.querySelector('.live-activity');if(!log)return;const row=document.createElement('div');row.className='log-row';row.innerHTML=`<time>${new Date().toLocaleTimeString('es-PA',{hour:'2-digit',minute:'2-digit'})}</time><i class="log-dot"></i><p><b>Red MOVIADS</b> · actividad actualizada en Obarrio</p>`;log.prepend(row);while(log.children.length>5)log.lastElementChild.remove()},4200);const l=LEADS.find(x=>x.name==='Clínica Sonrisa'),seq=[['typing','Agente MOVIADS está escribiendo…'],['msg','Hola, Dra. Elena. Vi que tienen dos sedes en Obarrio. ¿Les interesa aparecer cerca de sus pacientes?'],['typing','Clínica Sonrisa está escribiendo…'],['reply','Sí, buscamos algo para diciembre. ¿Podemos incluir el QR para agendar?'],['msg','Claro. Ya preparé una propuesta de 15 segundos para Obarrio con medición de escaneos.'],['hot','Lead actualizado · Tibio → Caliente']];let n=0;const tick=()=>{if(state.view!=='agentes'&&state.view!=='centro-agentes')return;if(n<seq.length){const [kind,text]=seq[n++];const row=document.createElement('div');row.className=`live-chat-row ${kind}`;row.textContent=text;box.querySelector('.live-chat-messages').append(row);if(kind==='hot'){state.leadHeat.l1='Caliente';save();const h=box.querySelector('.live-lead-heat');h.textContent='Caliente';h.classList.add('heat-hot');notice();}tickTimer(setTimeout(tick,kind==='typing'?1400:2100));}else{const log=box.querySelector('.live-activity');if(log){const row=document.createElement('div');row.className='log-row';row.innerHTML=`<time>${new Date().toLocaleTimeString('es-PA',{hour:'2-digit',minute:'2-digit'})}</time><i class="log-dot"></i><p><b>Clínica Sonrisa</b> · oportunidad calificada para Obarrio</p>`;log.prepend(row);while(log.children.length>5)log.lastElementChild.remove();}tickTimer(setTimeout(()=>{$$('.live-chat-row',box).forEach(x=>x.remove());n=0;tick()},5500));}};const tickTimer=t=>agentTimers.push(t);tick();}
function notice(){if(document.querySelector('.phone-notice'))return;const node=document.createElement('aside');node.className='phone-notice';node.innerHTML=`<span class="notice-icon">✳</span><div><strong>Agente de prospección · Clínica Sonrisa</strong><p>Quiere 15 segundos en Obarrio, te dejé la ficha lista</p><button class="button primary small" data-action="lead-detail" data-id="l1">Ver ficha</button></div><button class="notice-dismiss" data-action="notice-dismiss" aria-label="Cerrar">×</button>`;document.body.append(node);agentTimers.push(setTimeout(()=>node.remove(),9500));}
function agentLivePanel(){return `<section class="agent-live glass-card" id="agent-live"><div class="agent-live-top"><div><span class="kicker">CONVERSACIÓN EN VIVO · WHATSAPP</span><h2>Agente de prospección <span class="live-chip"><i></i> ${isAutonomous()?'trabajando':'esperando aprobación'}</span></h2></div><button class="button outline small" data-action="agent-repeat">Repetir</button></div><div class="live-chat-shell"><div class="live-chat-head"><span class="chat-avatar">CS</span><div><strong>Clínica Sonrisa</strong><small>WhatsApp · Obarrio</small></div><span class="live-lead-heat">Tibio</span></div><div class="live-chat-messages"><p class="chat-start">${isAutonomous()?'Simulación iniciada · hoy':'El agente preparó el contacto y espera tu respuesta'}</p></div></div><div class="live-activity"><div class="log-row"><time>08:42</time><i class="log-dot"></i><p><b>Agente de prospección</b> · inició contacto con Clínica Sonrisa</p></div></div></section>`}
function portal(c){const colors={Tropigas:'#15a595','McDonald’s':'#e6a71d',Novey:'#e76f4c','Denago EV':'#4d91d6',Cochez:'#d96750'};const color=colors[c.name]||'#15a595';const heat=c.zones.map((z,i)=>`<span style="--x:${14+i*18}%;--y:${26+(i%3)*23}%;--heat:${.5+(i%4)*.13}">${esc(z)}</span>`).join('');$('#overlay-root').innerHTML=`<section class="client-portal" style="--client-color:${color}" role="dialog" aria-modal="true"><header><a class="portal-brand" href="#">MOVIADS</a><div><span class="live-chip"><i></i> INFORME DE CAMPAÑA · NOVIEMBRE 2026</span><button class="button outline" data-action="portal-print">Imprimir</button><button class="button primary" data-action="portal-close">Cerrar ×</button></div></header><main><div class="portal-hero"><div><span class="kicker">ASÍ LO VE TU CLIENTE</span><h1>${esc(c.name)}</h1><p>${esc(c.campaign||'Cobertura en Ciudad de Panamá')} · ${esc(c.period||'Noviembre 2026')}</p></div><div class="portal-brand-block" aria-label="Identidad de ${esc(c.name)}">${esc(c.name.slice(0,1))}</div></div><div class="portal-kpis"><article><small>REPRODUCCIONES</small><strong data-portal-plays>${num(c.plays)}</strong><span>+8.4% frente a octubre</span></article><article><small>ESCANEOS QR</small><strong>${num(c.scans)}</strong><span>Acciones finales: ${num(c.actions)}</span></article><article><small>ZONAS CUBIERTAS</small><strong>${c.zones.length}</strong><span>Ciudad de Panamá</span></article><article><small>PROYECCIÓN</small><strong>${num(Math.round(c.plays*1.28))}</strong><span>Al subir un plan</span></article></div><div class="portal-grid"><section class="portal-card"><span class="kicker">COBERTURA EN LA CIUDAD</span><h2>Tu campaña recorrió estas zonas</h2><div class="portal-heat">${heat}<svg viewBox="0 0 1000 440" preserveAspectRatio="none"><path d="M35 330 Q210 270 355 190 T620 175 T950 65 M100 90 Q290 190 460 135 T850 350" fill="none" stroke="#ffffff55" stroke-width="5"/></svg></div></section><section class="portal-card"><span class="kicker">RESPUESTA POR HORA</span><h2>Escaneos del QR</h2><svg class="portal-chart" viewBox="0 0 600 210" aria-label="Escaneos QR a lo largo del día"><path d="M20 180 L20 144 70 132 120 145 170 104 220 114 270 75 320 91 370 45 420 66 470 30 520 56 580 18" fill="none" stroke="var(--client-color)" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" pathLength="1000" class="chart-draw"/><path d="M20 180 L20 144 70 132 120 145 170 104 220 114 270 75 320 91 370 45 420 66 470 30 520 56 580 18 L580 180Z" fill="var(--client-color)" opacity=".1"/></svg><div class="chart-labels"><span>6 a. m.</span><span>12 m.</span><span>6 p. m.</span><span>10 p. m.</span></div></section><section class="portal-card portal-compare"><span class="kicker">RESULTADO</span><h2>Más alcance, más oportunidades</h2><div class="compare-row"><span>Octubre</span><div><i style="width:72%"></i></div><strong>${num(Math.round(c.plays/1.084))}</strong></div><div class="compare-row current"><span>Noviembre</span><div><i style="width:86%"></i></div><strong>${num(c.plays)}</strong></div><p>Si subes de ${esc(c.plan)} a ${esc(PLANS[Math.max(0,PLANS.findIndex(p=>p.id===c.plan)-1)].id)}, la proyección alcanza ${num(Math.round(c.plays*1.28))} reproducciones.</p></section></div></main><footer><img src="./assets/logo-moviads.svg" alt=""><span>MOVIADS</span></footer></section>`;document.body.classList.add('portal-open');portalInterval=setInterval(()=>{livePlays+=14;const el=$('[data-portal-plays]');if(el)el.textContent=num(livePlays)},1000);}
function commandModal(){const allowed=new Set(navList().map(x=>x[0]));$('#overlay-root').innerHTML=`<div class="command-backdrop"><section class="command-box" role="dialog" aria-modal="true" aria-label="Buscar y preguntar en MOVIADS"><label class="command-search"><span aria-hidden="true">⌕</span><input id="command-input" placeholder="Busca un dato o escribe una pregunta…" autocomplete="off"><kbd>ESC</kbd></label><nav class="assistant-tabs"><button class="active" data-action="assistant-tab" data-tab="question">Pregunta</button><button data-action="assistant-tab" data-tab="task">Tarea</button></nav><div class="command-results" id="command-results"></div><div class="assistant-live-answer" id="assistant-live-answer" aria-live="polite"></div><div class="assistant-task-pane" id="assistant-task-pane" hidden></div><footer>↑ ↓ para explorar · Enter para responder</footer></section></div>`;document.body.classList.add('modal-open');renderCommandResults('');installIconGlyphs($('#overlay-root'));$('#command-input')?.focus();}
function renderCommandResults(raw){const box=$('#command-results');if(!box)return;const q=normalizeText(raw),allowed=new Set(navList().map(x=>x[0]));const modules=MODULES.filter(([id,label])=>allowed.has(id)&&matchScore(q,label)>0).map(([id,label])=>({kind:'module',label,meta:'Módulo',value:id,score:matchScore(q,label)}));const clients=CLIENTS.filter(c=>allowed.has('clientes')&&matchScore(q,c.name)>0).map(c=>({kind:'client',label:c.name,meta:'Cliente',value:c.id,score:matchScore(q,c.name)}));const units=FLEET.filter(f=>(allowed.has('flota')||allowed.has('mapa-vivo'))&&matchScore(q,`${f.id} ${f.zone} ${f.driver}`)>0).map(f=>({kind:'unit',label:f.id,meta:`Unidad · ${f.zone}`,value:f.id,score:matchScore(q,`${f.id} ${f.zone} ${f.driver}`)}));const phrase=raw.trim(),likelyQuestion=phrase.length>1&&(phrase.trim().split(/\s+/).length>=2||/[¿?]/.test(raw)||hasIntent(phrase,['cual','compar','mejor','peor','total','resumen','cuanto','cuanta','quien','cuando','donde','que','como','vend','venta','ingres','factur','gasto','ocupacion','libre','espacio','pantalla','escaneo','qr','lead','margen','utilidad','saldo','debe','pauta','zona','hora','recom']));let html=likelyQuestion?`<button data-action="assistant-answer" data-question="${esc(phrase)}"><span class="result-mark">${questionIcon}</span><strong>Preguntarle al Asistente</strong><small>Responder aquí</small></button>`:'';html+=[...modules,...clients,...units].sort((a,b)=>b.score-a.score).slice(0,8).map(x=>`<button data-action="command-go" data-kind="${x.kind}" data-value="${esc(x.value)}"><span class="result-mark">${x.kind==='module'?moduleIcon(x.value):x.kind==='client'?'<svg viewBox="0 0 24 24"><circle cx="9" cy="8" r="3"/><path d="M3 20v-1a6 6 0 0 1 12 0v1"/></svg>':'<svg viewBox="0 0 24 24"><path d="M3 13V7h11v9H3zm11-3h4l3 3v3h-7z"/><circle cx="7" cy="18" r="2"/></svg>'}</span><strong>${esc(x.label)}</strong><small>${esc(x.meta)}</small></button>`).join('');const prompts=['¿Cuánto se vendió el mes pasado?','¿Qué cliente tiene saldo pendiente?','¿Cuántos espacios METRO quedan?','¿Qué hago hoy?'];const related=prompts.filter(x=>!q||normalizeText(x).split(' ').some(w=>w.length>3&&q.includes(w)));html+=`<div class="suggested-questions"><small>${phrase?'PREGUNTAS SUGERIDAS':'PRUEBA PREGUNTAR'}</small>${related.slice(0,3).map(x=>`<button data-action="assistant-answer" data-question="${esc(x)}">${esc(x)}</button>`).join('')}</div>`;box.innerHTML=html||`<p class="command-hint">Escribe una pregunta sobre ventas, clientes, inventario, campañas, leads o la red.</p>`;const pane=$('#assistant-task-pane');if(pane&&!pane.hidden){const context=phrase||'Seguimiento del negocio';pane.innerHTML=`<form id="task-form" class="task-form"><article class="asked-data-card"><span class="kicker">DATO VINCULADO</span><strong>${esc(context)}</strong><p>Esta referencia quedará adjunta a la tarea.</p></article><label class="field-label">QUÉ HAY QUE HACER<input name="title" value="Revisar ${esc(context)}" required></label><label class="field-label">RESPONSABLE<select name="to">${allProfiles().map(p=>`<option value="${p.id}" ${p.id==='eric'?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="task-fields"><label class="field-label">FECHA LÍMITE<input name="due" type="date" value="2026-11-20" required></label><label class="field-label">PRIORIDAD<select name="priority"><option>Normal</option><option>Alta</option><option>Urgente</option></select></label></div><button class="button primary">Asignar tarea</button></form>`;}}
function paintAssistantAnswer(question){const result=answerRecord(question),host=$('#assistant-live-answer');if(!host)return;$('#command-results').hidden=true;const footer=$('.command-box footer');if(footer)footer.hidden=true;const suggestions=['¿Cuánto se vendió en octubre?','¿Qué cliente tiene saldo pendiente?','¿Cuántas pantallas están sin señal?'];if(!result){host.innerHTML=`<section class="answer-card answer-unknown"><p>No encuentro un dato confiable para responder eso.</p><small>Puedo consultar ventas, clientes, inventario, flota, campañas, medición, leads y gastos.</small><div>${suggestions.map(x=>`<button data-action="assistant-answer" data-question="${esc(x)}">${esc(x)}</button>`).join('')}</div></section>`;return;}const bars=(result.chart||[]).map((n,i,all)=>`<i style="height:${Math.max(14,Math.round(n/Math.max(...all)*60))}%" aria-label="${num(n)}"></i>`).join('');host.innerHTML=`<section class="answer-card"><span class="answer-overline">RESPUESTA</span><strong class="answer-value">${esc(result.value)}</strong><p>${esc(result.context)}</p>${bars?`<div class="answer-chart" aria-label="Comparación visual">${bars}</div>`:''}<small class="answer-source">Calculado con los datos de ${esc(result.period||'noviembre de 2026')}</small><div class="answer-actions"><button data-action="answer-finance" data-target="${esc(result.target||'finanzas')}">Ver en ${result.target==='finanzas'?'Finanzas':esc(moduleNames[result.target]||'MOVIADS')}</button><button data-action="answer-owner" data-module="${esc(result.target||'inicio')}" data-name="${esc(result.value)}" data-value="${esc(result.context)}" data-period="${esc(result.period||'noviembre 2026')}" data-target="${esc(result.target||'inicio')}">Preguntar al responsable</button><button data-action="assistant-tab" data-tab="task">Crear tarea</button></div></section>`;}
function home(){let offline=FLEET.filter(x=>x.status!=='online').length;const recs=[{id:'d1',text:'Tropigas registra 94% de sus reproducciones con 6 días de campaña. Proponer extensión.',action:'Renovar Tropigas',go:'clientes'},{id:'d2',text:'La pantalla 07 lleva 3 horas sin reportar. Revisar señal y unidad.',action:'Ver unidad MA-07',go:'flota'},{id:'d3',text:`Quedan ${packageAvailable(PLANS[1])} paquetes METRO disponibles para ${monthName(state.month)}.`,action:'Abrir inventario',go:'inventario'}];const labels={renewals:'Clientes por renovar','hot-leads':'Leads calientes',network:'Estado de la red',inventory:'Inventario disponible'},pref=userPrefs(),cards=pref.homeOrder.filter(x=>pref.homeCards.includes(x));
const homeCards=cards.map(id=>`<article class="home-personal-card"><button class="home-card-open" data-view="${id==='renewals'?'clientes':id==='hot-leads'?'agentes':id==='network'?'flota':'inventario'}"><small>${labels[id]}</small><strong>${id==='renewals'?'Tropigas':id==='hot-leads'?`${LEADS.filter(l=>l.heat==='Caliente').length} leads`:id==='network'?`${offline} alertas`:`${packageAvailable(PLANS[1])} paquetes`}</strong><span>${id==='renewals'?'Renueva el 30 de noviembre':id==='hot-leads'?'Con interés alto':id==='network'?'Unidades por revisar':`METRO · ${monthName(state.month)}`} ↗</span></button></article>`).join('');
const myTasks=(state.tasks||[]).filter(t=>t.to===profile().name&&!t.done);return `${myTasks.length?`<section class="section-block my-tasks"><div class="section-heading"><div><span class="kicker">ASIGNADAS A TI</span><h2>Mis tareas <b class="task-count">${myTasks.length}</b></h2></div><button class="text-link" data-view="mensajes">Abrir mensajes</button></div>${myTasks.map(t=>`<article class="my-task-row"><div><strong>${esc(t.title)}</strong><small>${esc(t.context)} · Vence ${esc(t.dueLabel)} · ${esc(t.priority)}</small></div><button class="button outline small" data-action="task-done" data-id="${t.id}">Marcar como hecha</button></article>`).join('')}</section>`:''}<section class="home-personal-cards">${homeCards}</section><section class="morning-band"><div class="morning-copy"><div class="eyebrow-light">MIÉRCOLES · RESUMEN DE OPERACIÓN</div><h2>Lo que pasó desde el cierre</h2><p>Actividad registrada hasta hoy, 8:50 a. m.</p></div><div class="morning-grid"><div><span class="metric-icon">✦</span><span>Leads nuevos</span><strong>${LEADS.length}</strong><small>${LEADS.filter(l=>l.heat==='Caliente').length} con interés alto</small></div><div><span class="metric-icon">↗</span><span>Campañas al aire</span><strong>${activeCampaigns()}</strong><small>En distribución</small></div><div><span class="metric-icon">◉</span><span>Ocupación de red</span><strong>${Math.round((soldCount()+reservedCount())/160*100)}%</strong><small>${soldCount()} de 160 espacios vendidos</small></div><div><span class="metric-icon">⌁</span><span>Unidades sin señal</span><strong>${offline}</strong><small>1 apagada · 1 sin reporte</small></div></div></section>${onAirScreen('inicio')}
<div class="home-columns"><section class="section-block"><div class="section-heading"><div><span class="kicker">DECISIONES SUGERIDAS</span><h2>Bandeja de revisión</h2></div><span class="count">${recs.filter(r=>!state.decisions[r.id]).length} pendientes</span></div><div class="decision-list">${recs.map(r=>state.decisions[r.id]?`<article class="decision-row resolved"><span class="decision-number">✓</span><div><p>${esc(r.text)}</p><small>Decisión ${state.decisions[r.id]}</small></div></article>`:`<article class="decision-row"><span class="decision-number">${String(recs.indexOf(r)+1).padStart(2,'0')}</span><div><p>${esc(r.text)}</p><small>Propuesta del sistema · ${r.go==='flota'?'Flota':'Comercial'}</small></div><div class="decision-actions"><button class="button primary small" data-action="decision" data-id="${r.id}" data-value="Aprobada" data-go="${r.go}">Aprobar</button><button class="button quiet small" data-action="decision" data-id="${r.id}" data-value="Descartada">Descartar</button></div></article>`).join('')}</div></section>
<aside class="right-stack"><section class="section-block compact"><div class="section-heading"><div><span class="kicker">COBRANZA</span><h2>Por cobrar</h2></div><button class="text-link" data-view="finanzas">Ver finanzas ↗</button></div><strong class="large-figure">${money(pendingReceivable())}</strong><p class="subline">4 facturas · 2 próximas a vencer</p><div class="thin-meter"><i style="width:68%"></i></div><div class="meter-labels"><span>68% al día</span><span>Noviembre</span></div></section><section class="section-block compact"><div class="section-heading"><div><span class="kicker">RED EN VIVO</span><h2>Estado de las pantallas</h2></div><button class="text-link" data-view="flota">Ver flota ↗</button></div><div class="status-line"><span class="status-mark good"></span><span>Encendidas y reportando</span><strong>18</strong></div><div class="status-line"><span class="status-mark off"></span><span>Apagada</span><strong>1</strong></div><div class="status-line"><span class="status-mark issue"></span><span>Sin señal reciente</span><strong>1</strong></div><div class="sparkline-wrap"><svg viewBox="0 0 420 52" role="img" aria-label="Actividad de la red durante el día"><path d="M0 43 L25 39 50 42 75 25 100 29 125 15 150 22 175 17 200 8 225 15 250 11 275 19 300 12 325 17 350 8 375 13 400 4 420 7" fill="none" stroke="#15A595" stroke-width="1.5"/><path d="M0 50 L0 43 L25 39 50 42 75 25 100 29 125 15 150 22 175 17 200 8 225 15 250 11 275 19 300 12 325 17 350 8 375 13 400 4 420 7 L420 50Z" fill="#15A595" opacity=".08"/></svg></div><div class="meter-labels"><span>6:00 a. m.</span><span>Actividad de red</span><span>9:00 a. m.</span></div></section></aside></div>
<section class="section-block home-lower"><div class="section-heading"><div><span class="kicker">OPERACIÓN</span><h2>Seguimiento de hoy</h2></div><span class="muted">Actualizado hace 4 min</span></div><div class="home-activity"><button data-view="programacion"><span class="activity-icon">01</span><span><strong>Distribución de pautas</strong><small>${CLIENTS.filter(c=>c.stage==='Activo').length} campañas listas para enviar a OnSign</small></span><b>Revisar ↗</b></button><button data-view="agentes"><span class="activity-icon">02</span><span><strong>Respuestas de prospección</strong><small>${LEADS.filter(l=>l.heat==='Caliente').length} leads con interés alto requieren seguimiento</small></span><b>Abrir ↗</b></button><button data-view="finanzas"><span class="activity-icon">03</span><span><strong>Facturación de noviembre</strong><small>4 clientes con saldo pendiente</small></span><b>Ver ↗</b></button></div></section>`}

function inventory(){const map=ensureMonth(state.month),free=160-soldCount(state.month)-reservedCount(state.month);return `<section class="inventory-intro"><div><span class="kicker">CAPACIDAD DE RED</span><div class="capacity-title"><strong>20</strong><span>pantallas</span><i></i><strong>8</strong><span>espacios por loop</span></div><p>Un espacio equivale a una marca del loop. Cada unidad tiene dos caras LED. A plena ocupación, la capacidad estimada se acerca a 2.8 millones de reproducciones al mes.</p></div><label class="month-picker">PERÍODO<input type="month" id="inventory-month" value="${state.month}"></label></section><div class="inventory-summary"><div><span>Espacios vendidos</span><strong>${soldCount()}</strong><small>de 160 · ${reservedCount()} reservados</small></div><div><span>Espacios disponibles</span><strong>${free}</strong><small>incluye inventario no reservado</small></div><div><span>Reproducciones estimadas</span><strong>${num(soldCount()*45*13*30)}</strong><small>proyección · 13 h × 30 días</small></div><button class="button primary" data-action="sale">Simular venta +</button></div><section class="section-block"><div class="section-heading"><div><span class="kicker">PAQUETES MOVIADS</span><h2>Disponibilidad en ${esc(monthName(state.month))}</h2></div><span class="quiet-note">Precios de ejemplo · Cotización según duración</span></div><div class="plan-grid">${PLANS.map(p=>`<div class="plan-cell plan-${p.id.toLowerCase()}" style="--plan-color:${['#ff806b','#15a595','#6e9bd8','#9487f5','#45bbd3','#173a7a'][PLANS.indexOf(p)]}"><span>${p.id}</span><strong>${packageAvailable(p)}</strong><small>${p.screens} ${p.screens===1?'pantalla':'pantallas'} por paquete</small><div class="plan-track"><i style="width:${Math.min(100,Math.max(8,packageAvailable(p)*10))}%"></i></div></div>`).join('')}</div></section><section class="section-block matrix-section"><div class="section-heading"><div><span class="kicker">INVENTARIO DE RED</span><h2>Unidades y espacios</h2></div><div class="view-switch"><button class="active" data-action="inventory-view" data-value="rings">Anillos</button><button data-action="inventory-view" data-value="matrix">Matriz</button></div></div><div class="ring-inventory">${Object.entries(map).map(([id,row])=>{const sold=row.filter(x=>x?.kind==='vendido').length,res=row.filter(x=>x?.kind==='reservado').length,freeN=8-sold-res;return `<article class="ring-unit" data-id="${id}"><button class="ring-open" data-action="unit" data-id="${id}"><span class="ring" style="background:conic-gradient(${row.map((x,i)=>`${x?.kind==='vendido'?'#173a7a':x?.kind==='reservado'?'#6e9bd8':'#e1e9ef'} ${i*45}deg ${i*45+42}deg,#ffffff ${i*45+42}deg ${(i+1)*45}deg`).join(',')})"><b>${sold+res}<small>/8</small></b></span><strong>${id}</strong><small>${esc(FLEET[Number(id.slice(-2))-1].zone)}</small></button></article>`}).join('')}</div><div class="ring-legend"><span><i class="legend-swatch sold"></i>Vendido</span><span><i class="legend-swatch reserved"></i>Reservado</span><span><i class="legend-swatch free"></i>Libre</span></div><div class="matrix-view" hidden><div class="legend"><span><i class="legend-swatch sold"></i>Vendido</span><span><i class="legend-swatch reserved"></i>Reservado</span><span><i class="legend-swatch free"></i>Libre</span></div><div class="legend"><span><i class="legend-swatch sold"></i>Vendido</span><span><i class="legend-swatch reserved"></i>Reservado</span><span><i class="legend-swatch free"></i>Libre</span></div></div><div class="table-scroll"><table class="matrix-table"><thead><tr><th>Pantalla</th>${Array.from({length:8},(_,i)=>`<th>ESP ${String(i+1).padStart(2,'0')}</th>`).join('')}<th>Red</th></tr></thead><tbody>${Object.entries(map).map(([id,row])=>`<tr><th><span class="unit-code">${id}</span><small>${FLEET[Number(id.slice(-2))-1].zone}</small></th>${row.map((x,j)=>`<td><button class="space-cell ${x?x.kind:'free'}" title="${x?`${x.client} · ${x.plan}`:'Espacio disponible'}" data-action="slot" data-unit="${id}" data-slot="${j}">${x?esc(x.client):'Libre'}</button></td>`).join('')}<td class="row-capacity">${row.filter(Boolean).length}/8</td></tr>`).join('')}</tbody></table></div><div class="mobile-matrix">${Object.entries(map).map(([id,row])=>`<article class="mobile-screen-card"><header><strong>${id}</strong><span>${FLEET[Number(id.slice(-2))-1].zone}</span><small>${row.filter(Boolean).length}/8 espacios</small></header><div>${row.map((x,j)=>`<button class="space-cell ${x?x.kind:'free'}" data-action="slot" data-unit="${id}" data-slot="${j}"><span>${String(j+1).padStart(2,'0')}</span>${x?esc(x.client):'Libre'}</button>`).join('')}</div></article>`).join('')}</div></div><p class="footnote">Estimación de referencia: un anuncio de 10 segundos en loop de 8 marcas se reproduce cerca de 45 veces por hora en cada pantalla.</p></section>`}

function scheduling(){let campaigns=[...CLIENTS.filter(c=>c.stage==='Activo').map((c,i)=>({id:`PA-${String(i+21).padStart(3,'0')}`,client:c.name,creative:c.creative,plays:c.plays,target:c.target,plan:c.plan,sync:state.sync[`PA-${String(i+21).padStart(3,'0')}`]||(i===2?'Pendiente de envío':'Sincronizado'),progress:Math.round(c.plays/c.target*100),zone:c.zones[0]})),...state.campaigns.map(c=>({...c,sync:state.sync[c.id]||c.sync}))];return `<section class="section-block schedule-banner"><div><span class="kicker">DISTRIBUCIÓN AUTOMÁTICA</span><h2>De la pauta contratada a la red</h2><p>El sistema propone una frecuencia por pantalla y franja, y deja el paquete listo para sincronizar con OnSign.</p></div><button class="button primary" data-action="campaign">Crear pauta +</button></section><div class="schedule-stats"><div><span>Al aire hoy</span><strong>${campaigns.length}</strong></div><div><span>Sincronizadas</span><strong>${campaigns.filter(c=>c.sync==='Sincronizado').length}</strong></div><div><span>Requieren revisión</span><strong>${campaigns.filter(c=>c.progress<94||c.sync!=='Sincronizado').length}</strong></div><div><span>Frecuencia base</span><strong>45 <small>/h</small></strong></div></div><section class="section-block"><div class="section-heading"><div><span class="kicker">PAUTAS ACTIVAS</span><h2>Entrega y sincronización</h2></div><span class="quiet-note">10 s por marca · 8 marcas máximo por loop</span></div><div class="campaign-list">${campaigns.map(c=>`<article class="campaign-row"><div class="campaign-id">${esc(c.id)}<small>${esc(c.plan)}</small></div><div class="campaign-client"><strong>${esc(c.client)}</strong><small>${esc(c.creative||'Creativo pendiente')} · ${esc(c.zone||'Cobertura contratada')}</small></div><div class="campaign-progress"><div><span>Reproducciones entregadas</span><strong>${num(c.plays)} / ${num(c.target)}</strong></div><div class="progress-line"><i class="${c.progress<90?'behind':''}" style="width:${Math.min(c.progress,100)}%"></i></div></div><span class="sync-state ${c.sync==='Sincronizado'?'ok':''}">${esc(c.sync)}</span><button class="button quiet small" data-action="${c.sync==='Sincronizado'?'pauta':'sync'}" data-id="${esc(c.id)}">${c.sync==='Sincronizado'?'Ver pauta':'Enviar a OnSign'}</button></article>`).join('')}</div></section><section class="section-block schedule-grid"><div><span class="kicker">DISTRIBUCIÓN PROPUESTA</span><h2>Por franja de operación</h2><div class="hour-chart">${[['6–9 a. m.',38],['9–12 p. m.',57],['12–3 p. m.',68],['3–6 p. m.',91],['6–9 p. m.',73]].map(x=>`<div><i style="height:${x[1]}%"></i><span>${x[0]}</span></div>`).join('')}</div></div><div class="schedule-note"><span class="kicker">REGLA DE ENTREGA</span><p>El sistema reparte las reproducciones contratadas entre las pantallas del plan, los días de vigencia y las horas activas. OnSign mantiene el control de reproducción en pantalla.</p><button class="text-link" data-view="conexiones">Revisar conexión OnSign ↗</button></div></section>`}

function clients(){let list=CLIENTS;return `<section class="section-block client-toolbar"><div class="filter-tabs"><button class="filter-tab active" data-filter="all">Todos <b>${list.length}</b></button>${['Activo','Propuesta','Prospecto'].map(s=>`<button class="filter-tab" data-filter="${s}">${s}</button>`).join('')}</div><label class="search-box"><span>⌕</span><input id="client-search" placeholder="Buscar cliente"></label></section><section class="client-list" id="client-list">${list.map(c=>clientRow(c)).join('')}</section>`}
function clientRow(c){return `<article class="client-row" data-client-row data-name="${esc(c.name.toLowerCase())}" data-stage="${c.stage}"><span class="client-monogram">${c.name.slice(0,2).toUpperCase()}</span><div class="client-main"><strong>${esc(c.name)}</strong><small>${esc(c.contact)} · ${esc(c.history)} · Socio ${esc(allProfiles().find(p=>p.id===clientOwner(c))?.name||'Ana Victoria')}</small></div><span class="stage-label ${c.stage==='Activo'?'active':c.stage==='Propuesta'?'proposal':''}">${esc(c.stage)}</span><div class="client-campaign"><strong>${esc(c.campaign||'Sin campaña activa')}</strong><small>${esc(c.plan)}${c.period?' · '+esc(c.period):''}</small></div>${canMargin()?`<div class="client-value"><strong>${money(c.revenue)}</strong><small>facturación</small></div>`:''}<button class="text-link" data-action="client" data-id="${c.id}">Abrir ficha ↗</button></article>`}

function measurement(){const client=CLIENTS.find(c=>c.name===state.customer)||CLIENTS[0];const currentPlan=PLANS.find(p=>p.id===client.plan)||PLANS[2],planIndex=PLANS.findIndex(p=>p.id===client.plan),nextPlan=PLANS[Math.max(0,planIndex-1)],projectedScans=client.scans?Math.round(client.scans*nextPlan.screens/currentPlan.screens):0;const heat=[22,38,31,48,62,78,94,82,66,54,72,91,84,60,46,39,31,28,43,58,74,61,42,25];const points=[[33,48,'Balboa'],[42,37,'Obarrio'],[50,52,'San Francisco'],[63,61,'Costa del Este'],[69,76,'Tocumen'],[52,31,'El Cangrejo'],[30,59,'Paitilla'],[46,24,'Albrook'],[57,40,'Vía España'],[74,54,'Juan Díaz']];return `<div class="measurement-top"><section class="map-panel"><div class="map-heading"><div><span class="kicker">TRAZADO DE RED</span><h2>Ciudad de Panamá</h2></div><button class="button outline small" data-action="client-portal" data-id="${client.id}">Así lo ve tu cliente ↗</button></div><div class="city-map"><svg viewBox="0 0 800 460" preserveAspectRatio="xMidYMid slice" aria-label="Mapa esquemático de Ciudad de Panamá"><rect width="800" height="460" fill="#eff5f7"/><path d="M-20 373 Q75 326 151 344T294 321T432 322T562 281T828 238L830 470H-20Z" fill="#c9e4ea"/><path id="route-main" d="M44 310 C138 273 196 288 280 231 S410 210 478 179 S601 171 733 91" fill="none" stroke="#173A7A" stroke-width="4" opacity=".78"/><circle r="7" fill="#ff806b" stroke="#fff" stroke-width="3"><title>Unidad en ruta</title><animateMotion dur="14s" repeatCount="indefinite" rotate="auto"><mpath href="#route-main"/></animateMotion></circle><path d="M69 117 C146 167 231 137 321 193 S490 237 620 207 S730 229 790 279" fill="none" stroke="#6E9BD8" stroke-width="3" opacity=".75"/><path d="M184 405 C240 335 271 275 331 225 S409 165 449 65" fill="none" stroke="#15A595" stroke-width="3" opacity=".82"/><path d="M90 200 L237 192 320 231 400 208 478 179 562 193 673 160 M276 60 L303 143 321 193 290 280 270 360 M463 40 L449 130 478 179 467 276 509 361" fill="none" stroke="#b5c8d2" stroke-width="1.5"/><g fill="#4F5867" font-family="IBM Plex Sans" font-size="13"><text x="57" y="281">Balboa</text><text x="330" y="160">Obarrio</text><text x="417" y="244">San Francisco</text><text x="578" y="230">Costa del Este</text><text x="658" y="302">Tocumen</text><text x="191" y="183">Albrook</text><text x="350" y="281">Paitilla</text><text x="501" y="150">Vía España</text><text x="260" y="107">El Cangrejo</text></g><g>${points.map((p,i)=>`<g transform="translate(${p[0]*8},${p[1]*4.3})"><circle r="9" fill="#0B1F4A" opacity=".12"/><circle r="5" fill="#15A595" stroke="#fff" stroke-width="2"><title>${p[2]} · unidad ${String(i+1).padStart(2,'0')}</title></circle></g>`).join('')}</g><g class="map-route-dots">${Array.from({length:30},(_,i)=>`<circle cx="${80+i*21}" cy="${350-Math.sin(i*.52)*45}" r="2.3" fill="#6E9BD8" opacity=".6"/>`).join('')}</g></svg><div class="map-legend"><span><i class="map-dot"></i>Pantalla en ruta</span><span><i class="map-line"></i>Corredor ilustrativo</span><small>El trazado no representa GPS en tiempo real</small></div></div></section><aside class="measurement-aside"><section class="section-block compact"><span class="kicker">REPRODUCCIONES · NOVIEMBRE</span><strong class="metric-large">${num(CLIENTS.reduce((a,c)=>a+c.plays,0))}</strong><small>registradas en la red</small><div class="sparkline-wrap big"><svg viewBox="0 0 320 70"><path d="M0 58 L22 48 45 51 68 34 91 38 114 25 137 31 160 12 183 23 206 19 229 7 252 18 275 12 298 5 320 9" fill="none" stroke="#15A595" stroke-width="2"/></svg></div><span class="comparison">+8.4% frente a octubre</span></section><section class="section-block compact"><span class="kicker">REGISTRO PARA AUDITORÍA</span><div class="audit-facts"><span>Fecha y hora<strong>Por reproducción</strong></span><span>Equipo<strong>20 unidades</strong></span><span>Coordenada<strong>GPS registrado</strong></span></div></section></aside></div><div class="measurement-columns"><section class="section-block"><div class="section-heading"><div><span class="kicker">ACTIVIDAD POR ZONA</span><h2>Reproducciones y escaneos</h2></div><span class="quiet-note">Noviembre 2026</span></div><div class="zone-list">${[['San Francisco',42800,219],['Costa del Este',37600,184],['Obarrio',33900,176],['Vía España',29800,161],['Tocumen',24700,131],['Balboa y Paitilla',21600,97]].map(z=>`<div><span>${z[0]}</span><div class="zone-bar"><i style="width:${z[1]/45000*100}%"></i></div><strong>${num(z[1])}</strong><small>${z[2]} QR</small></div>`).join('')}</div><div class="hour-heat"><span class="kicker">MAPA DE CALOR · POR HORA</span><div>${heat.map((v,i)=>`<i title="${i}:00 · índice ${v}" style="--heat:${v/100}"></i>`).join('')}</div><div class="heat-labels"><span>12 a. m.</span><span>6 a. m.</span><span>12 p. m.</span><span>6 p. m.</span><span>11 p. m.</span></div></div></section><section class="section-block qr-panel"><div class="section-heading"><div><span class="kicker">MEDICIÓN DE QR</span><h2>Escaneos y acciones</h2></div></div><label class="field-label">CAMPAÑA<select id="customer-select">${CLIENTS.filter(c=>c.stage==='Activo').map(c=>`<option ${c.name===client.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="qr-numbers"><div><span>Escaneos</span><strong>${num(client.scans)}</strong><small>por pantalla, zona y hora</small></div><div><span>Acción final</span><strong>${num(client.actions)}</strong><small>formularios o clics</small></div></div><div class="conversion-row"><span>Tasa de acción</span><strong>${client.scans?Math.round(client.actions/client.scans*100):0}%</strong><i style="width:${client.scans?client.actions/client.scans*100:0}%"></i></div><div class="scan-screen-list"><span class="kicker">MUESTRA DE ESCANEOS POR PANTALLA</span><div><b>MA-03</b><span>Obarrio · 5:00 p. m.</span><strong>68</strong></div><div><b>MA-11</b><span>Costa del Este · 7:00 p. m.</span><strong>54</strong></div><div><b>MA-14</b><span>Vía España · 6:00 p. m.</span><strong>43</strong></div></div><p class="projection"><b>Proyección</b> Si ${esc(client.name)} pasa de ${client.plan} a ${nextPlan.id}, la proyección es de ${num(projectedScans)} escaneos el próximo mes, según el histórico de zonas y frecuencia.</p><button class="button primary full" data-action="report" data-client="${esc(client.name)}">Generar reporte del cliente</button></section></div>`}

function agentCenter(){return `${agentLivePanel()}<section class="agent-network glass-card"><header class="section-heading"><div><span class="kicker">CENTRO DE AGENTES</span><h2>Seis áreas, una sola operación</h2></div><span class="live-chip"><i></i> 2 flujos activos</span></header><div class="agent-flow"><div class="flow-node"><small>MEDICIÓN</small><b>${num(CLIENTS.find(c=>c.name==='McDonald’s')?.scans||0)} escaneos</b><span>McDonald’s · escaneos registrados</span></div><span class="flow-link"><i></i><b>señal de respuesta</b></span><div class="flow-node warm"><small>PROSPECCIÓN</small><b>Extensión sugerida</b><span>Revisar con el equipo</span></div><span class="flow-link"><i></i><b>entrega a red</b></span><div class="flow-node sky"><small>PROGRAMACIÓN</small><b>${FLEET.filter(f=>f.status==='online').length} pantallas al aire</b><span>Reparto de pauta</span></div></div><div class="agent-grid">${[['Prospección de anunciantes','✳',`${LEADS.length} prospectos`,`${LEADS.filter(l=>l.heat==='Caliente').length} leads calientes`, 'Consultar antes de escribir','agent-teal'],['Flota y conductores','◇',`${FLEET.length} unidades`,`${FLEET.filter(f=>f.status!=='online').length} alertas por revisar`,'Revisar respuestas','agent-sky'],['Programador de pautas','◷',`${CLIENTS.filter(c=>c.stage==='Activo').length} campañas activas`,'Pautas listas para enviar','Consultar antes de enviar','agent-blue'],['Cobranza y contabilidad','＄',`${CLIENTS.filter(c=>c.stage==='Activo').length} cuentas activas`,'Saldos disponibles en Finanzas','Manual','agent-warm'],['Medición y reportes','⌁',`${num(CLIENTS.reduce((n,c)=>n+c.scans,0))} escaneos registrados`,'Lecturas de campañas activas','Consultar antes de exportar','agent-violet'],['Conductores y pantallas','◎',`${FLEET.filter(f=>f.status==='online').length} pantallas reportando`,`${FLEET.filter(f=>f.status!=='online').length} casos en seguimiento`,'Supervisión','agent-cyan']].map(a=>`<article class="agent-unit ${a[5]}"><header><span class="unit-symbol">${a[1]}</span><span class="live-chip"><i></i> Activo</span></header><h3>${a[0]}</h3><div class="agent-unit-stats"><div><b>${a[2]}</b><small>anoche</small></div><div><b>${a[3]}</b><small>por aprobar</small></div></div><footer><span>Autonomía</span><strong>${a[0]==='Prospección de anunciantes'?esc(effectiveAutonomy()):a[4]}</strong></footer></article>`).join('')}</div><section class="agent-log"><div class="section-heading"><div><span class="kicker">COORDINACIÓN</span><h2>Actividad reciente</h2></div><span class="quiet-note">Basado en datos de ejemplo</span></div>${(state.agentLog||[]).map(x=>`<div class="log-row brain-log-row"><time>${esc(x.time)}</time><span class="log-dot teal"></span><p><b>${esc(x.area)}</b> aprobó la recomendación: ${esc(x.text)}</p></div>`).join('')}<div class="log-row"><time>8:42 a. m.</time><span class="log-dot teal"></span><p><b>Prospección</b> recibió respuesta de Clínica Sonrisa y dejó una propuesta de reunión.</p></div><div class="log-row"><time>8:15 a. m.</time><span class="log-dot sky"></span><p><b>Programación</b> preparó las campañas activas para distribución.</p></div><div class="log-row"><time>7:38 a. m.</time><span class="log-dot warm"></span><p><b>Flota</b> registró seguimiento pendiente para la unidad MA-07.</p></div></section></section>`}
function agents(){const type=state.agentType||'anunciantes';const sectors=type==='conductores'?['Conductores de plataforma','Conductores Uber','Conductores independientes']:['Clínicas dentales','Restaurantes y cafeterías','Ferreterías','Concesionarios'];const leads=LEADS.filter(l=>type==='conductores'?l.sector==='Conductor':l.sector!=='Conductor');const heat=l=>state.leadHeat[l.id]||l.heat;return `<section class="agent-hero"><div><span class="kicker light">DOS FLUJOS DE PROSPECCIÓN</span><h2>Buscar. Conversar. Clasificar.</h2><p>Revisa la conversación y decide cuánta autonomía tiene el agente por usuario.</p></div><div class="agent-tabs"><button class="${type==='anunciantes'?'active':''}" data-action="agent-type" data-value="anunciantes">Anunciantes</button><button class="${type==='conductores'?'active':''}" data-action="agent-type" data-value="conductores">Conductores</button></div></section><div class="agent-controls"><label class="field-label">RUBRO<select id="agent-sector">${sectors.map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field-label">ZONA<select id="agent-zone">${ZONES.map(z=>`<option ${z==='Obarrio'?'selected':''}>${z}</option>`).join('')}</select></label><button class="button primary" data-action="run-agent">Buscar prospectos</button><button class="button quiet" data-action="simulate-notice">Simular aviso</button></div><div class="autonomy-banner"><div><span class="kicker">AGENTE PERSONAL</span><strong>${esc(profile().name)} · ${esc(effectiveAutonomy())}</strong><small>${esc(agentConfig().channel)} · ${agentConfig().maxPerLead} mensajes por lead al día</small></div><button class="button outline small" data-view="mi-agente">Configurar mi agente ↗</button></div><section class="kanban"><div class="kanban-top"><div><span class="kicker">CONVERSACIONES</span><h2>Estado del prospecto</h2></div><span class="quiet-note">${leads.length} registros de ejemplo · mueve con selector</span></div><div class="kanban-columns">${['Frío','Tibio','Caliente','Reunión agendada'].map(stage=>`<div class="kanban-col"><header><span>${stage}</span><strong>${leads.filter(l=>heat(l)===stage).length}</strong></header>${leads.filter(l=>heat(l)===stage).map(l=>`<article class="lead-card"><div class="lead-card-top"><strong>${esc(l.name)}</strong><button data-action="lead-detail" data-id="${l.id}" aria-label="Ver conversación">↗</button></div><span>${esc(l.sector)} · ${esc(l.zone)}</span><p>${esc(l.intent)}</p><small>${esc(l.last)} · ${esc(l.channel)}</small><label class="lead-stage-select">CLASIFICACIÓN<select data-lead-heat="${l.id}">${['Frío','Tibio','Caliente','Reunión agendada'].map(x=>`<option ${x===heat(l)?'selected':''}>${x}</option>`).join('')}</select></label>${l.budget?`<div class="lead-budget"><span>${l.seconds} s · ${l.plan}</span><strong>${money(l.budget)}</strong></div>`:''}<button class="text-link" data-action="lead-detail" data-id="${l.id}">Ver conversación ↗</button></article>`).join('')||'<p class="empty-column">Sin prospectos en esta etapa</p>'}</div>`).join('')}</div></section>`}

function fleet(){return `<section class="fleet-hero"><div><span class="kicker light">OPERACIÓN DE PANTALLAS</span><h2>20 unidades en cobertura</h2><p>Estado de la pantalla, actividad registrada y zonas recorridas.</p></div><div class="fleet-total"><strong>18</strong><span>encendidas</span><small>1 apagada · 1 sin señal</small></div></section><div class="fleet-toolbar"><div class="filter-tabs"><button class="filter-tab active" data-fleet-filter="all">Todas · 20</button><button class="filter-tab" data-fleet-filter="online">En línea · 18</button><button class="filter-tab" data-fleet-filter="off">Apagadas · 1</button><button class="filter-tab" data-fleet-filter="offline">Sin señal · 1</button></div><label class="search-box"><span>⌕</span><input id="fleet-search" placeholder="Buscar unidad o conductor"></label></div><section class="fleet-grid" id="fleet-grid">${FLEET.map(f=>`<article class="fleet-card" data-fleet-item data-status="${f.status}" data-search="${f.id.toLowerCase()} ${f.driver.toLowerCase()} ${f.car.toLowerCase()}"><div class="fleet-photo"><img src="./assets/${f.image}" alt="Vehículo de la flota MOVIADS"><span class="screen-state ${f.status}"><i></i>${f.status==='online'?'Pantalla encendida':f.status==='off'?'Pantalla apagada':'Sin señal'}</span><b>${f.id}</b></div><div class="fleet-card-body"><div class="fleet-car"><div><strong>${esc(f.car)}</strong><small>${esc(f.driver)}</small></div><button class="icon-btn small-icon" data-action="unit" data-id="${f.id}" aria-label="Ver unidad">↗</button></div><div class="fleet-facts"><span>Horas activas<strong>${f.hours.toFixed(1)} h</strong></span><span>Recorrido<strong>${num(f.km)} km</strong></span><span>Zona reciente<strong>${esc(f.zone)}</strong></span><span>Conducción<strong>${esc(f.behavior)}</strong></span></div><div class="fleet-card-foot"><span>Incentivo de ejemplo</span><strong>${money(f.incentive)}</strong></div></div></article>`).join('')}</section>`}

function financeSummary(){const revenue=CLIENTS.reduce((a,c)=>a+c.revenue,0)+state.campaigns.reduce((a,c)=>a+c.value,0)+state.sales.filter(x=>x.month==='2026-11').reduce((a,x)=>a+x.value,0),cost=CLIENTS.reduce((a,c)=>a+c.cost,0)+(state.expenses||[]).reduce((a,x)=>a+x.total,0);return `<div class="finance-top"><section class="section-block finance-primary"><span class="kicker">INGRESOS · NOVIEMBRE 2026</span><strong>${money(revenue)}</strong><div class="finance-trend"><span>Por cobrar</span><b>${money(pendingReceivable())}</b><i>4 documentos pendientes</i></div><button class="text-link" data-action="ask-accountant" data-amount="Ingresos de noviembre · ${money(revenue)}">Preguntar ↗</button></section><section class="section-block finance-secondary"><span class="kicker">GASTOS FIJOS · EJEMPLO</span><strong>${money(3850)}</strong><p>Combustible · conectividad · mantenimiento</p><button class="text-link" data-action="ask-accountant" data-amount="Gastos fijos · noviembre · ${money(3850)}">Preguntar ↗</button></section>${canMargin()?`<section class="section-block finance-secondary"><span class="kicker">MARGEN DE CAMPAÑAS</span><strong>${money(revenue-cost)}</strong><p>Ingresos ${money(revenue)} · costos directos ${money(cost)}</p><button class="text-link" data-action="ask-accountant" data-amount="Margen de campañas · noviembre · ${money(revenue-cost)}">Preguntar ↗</button></section>`:''}</div><section class="section-block invoice-section"><div class="section-heading"><div><span class="kicker">CUENTAS POR CLIENTE</span><h2>Facturación del mes</h2></div><span class="quiet-note">Importes y documentos de ejemplo</span></div><div class="invoice-list">${CLIENTS.filter(c=>c.stage==='Activo').map((c,i)=>{const paid=i===1||i===3||i===5,issued=state.invoices.some(x=>x.client===c.name);return `<article class="invoice-row"><div class="invoice-date">${String(26-i).padStart(2,'0')}<small>NOV</small></div><div class="invoice-client"><strong>${esc(c.name)}</strong><small>Factura FV-2026-${String(441+i).padStart(4,'0')} · ${esc(c.plan)}</small></div><div class="invoice-status ${paid?'paid':''}">${paid?'Pagada':issued?'Emitida · pendiente':'Pendiente'}</div><strong class="invoice-amount">${money(c.revenue)}</strong>${paid||issued?`<button class="text-link" data-action="invoice-view" data-id="${c.id}">Ver factura ↗</button>`:`<button class="button primary small" data-action="invoice" data-id="${c.id}">Emitir factura</button>`}<button class="text-link" title="Preguntar" data-action="ask-accountant" data-amount="Factura de ${esc(c.name)} · ${money(c.revenue)}">Preguntar ↗</button></article>`}).join('')}</div><p class="footnote">La emisión muestra una representación de factura electrónica con CUFE y QR. No conecta con la DGI.</p></section><section class="finance-bottom"><div class="section-block"><div class="section-heading"><div><span class="kicker">INGRESOS</span><h2>Actividad mensual</h2></div></div><div class="revenue-chart">${[58,73,66,84,69,92,77,100,82,88,75,94].map((n,i)=>`<div><i style="height:${n}%"></i><span>${['D','E','F','M','A','M','J','J','A','S','O','N'][i]}</span></div>`).join('')}</div></div><div class="section-block">${canMargin()?`<span class="kicker">MEZCLA DE CAMPAÑAS</span><h2>Costos y contribución</h2><div class="cost-line"><span>Costos directos de pauta</span><strong>${money(cost)}</strong></div><div class="cost-track"><i style="width:${cost/revenue*100}%"></i></div><div class="cost-line"><span>Contribución de campañas</span><strong>${money(revenue-cost)}</strong></div>`:profile().access==='finance'?`<span class="kicker">COSTOS DE OPERACIÓN</span><h2>Costos directos</h2><div class="cost-line"><span>Costos directos de pauta</span><strong>${money(cost)}</strong></div><div class="cost-line"><span>Gastos fijos de operación</span><strong>${money(3850)}</strong></div><button class="text-link" data-action="ask-accountant" data-amount="Costos directos · ${money(cost)}">Preguntar ↗</button>`:`<span class="kicker">SEGUIMIENTO DE COBROS</span><h2>Próximos vencimientos</h2><p>McDonald’s · vence el 28 de noviembre</p><p>Denago EV · vence el 30 de noviembre</p><p>Revisa la bandeja de facturas para ver el estado.`}</div></section>`}

const expenseCategories=['Combustible','Mantenimiento de unidades','Insumos de pantallas LED','Conectividad','Publicidad','Oficina'];
function financeTabs(){const tabs=[['resumen','Resumen'],['contabilidad','Contabilidad'],['facturacion','Facturación DGI'],['gastos','Gastos y compras con IA']];return `<nav class="finance-tabs" aria-label="Secciones de finanzas">${tabs.map(([id,label])=>`<button class="${(state.financeTab||'resumen')===id?'active':''}" data-action="finance-tab" data-value="${id}">${label}</button>`).join('')}</nav>`}
function finance(){const tab=state.financeTab||'resumen';if(tab==='resumen')return `${financeTabs()}${financeSummary()}${cashflowChart()}`;if(tab==='contabilidad')return `${financeTabs()}${accountingView()}`;if(tab==='facturacion')return `${financeTabs()}${dgiView()}`;return `${financeTabs()}${expensesView()}`}
function cashflowChart(){const revenue=pendingReceivable(),fixed=3850,points=[0,.18,.34,.5,.66,.82,1].map((v,i)=>({x:36+i*112,y:24+90*(1-v*(revenue?1:0))}));const line=points.map((p,i)=>`${i?'L':'M'}${p.x} ${p.y}`).join(' ');return `<section class="section-block cashflow-card"><div class="section-heading"><div><span class="kicker">PROYECCIÓN · 30 DÍAS</span><h2>Flujo de caja estimado</h2></div><span class="quiet-note">Cobros pendientes menos gastos fijos</span></div><div class="cashflow-total">${money(revenue-fixed)} <small>saldo neto estimado</small></div><svg viewBox="0 0 760 150" role="img" aria-label="Curva proyectada de flujo de caja"><defs><linearGradient id="cashFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#15a595" stop-opacity=".3"/><stop offset="1" stop-color="#15a595" stop-opacity="0"/></linearGradient></defs><path d="${line} L708 140 L36 140 Z" fill="url(#cashFill)"/><path d="${line}" fill="none" stroke="#15a595" stroke-width="3" stroke-linecap="round"/>${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="#fff" stroke="#15a595" stroke-width="2"/>`).join('')}</svg><div class="cashflow-axis"><span>Hoy</span><span>+10 días</span><span>+20 días</span><span>+30 días</span></div></section>`}
function accountingView(){const revenue=CLIENTS.reduce((n,c)=>n+c.revenue,0)+state.campaigns.reduce((n,c)=>n+c.value,0)+state.sales.filter(x=>x.month==='2026-11').reduce((n,x)=>n+x.value,0),direct=CLIENTS.reduce((n,c)=>n+c.cost,0),incentives=FLEET.reduce((n,f)=>n+f.incentive,0),fixed=3850,expenses=(state.expenses||[]).reduce((n,x)=>n+x.total,0),profit=revenue-direct-incentives-fixed-expenses,byPlan=PLANS.map(p=>({plan:p.id,total:CLIENTS.filter(c=>c.plan===p.id).reduce((n,c)=>n+c.revenue,0)+state.sales.filter(c=>c.plan===p.id&&c.month==='2026-11').reduce((n,c)=>n+c.value,0)}));return `<section class="section-block accounting-card"><header class="section-heading"><div><span class="kicker">ESTADO DE RESULTADOS · NOVIEMBRE 2026</span><h2>Ingresos y costos del mes</h2></div><button class="button outline" data-action="export-accounting">Exportar a Excel ↓</button></header><div class="table-scroll"><table class="accounting-table"><tbody><tr class="table-section"><th colspan="3">Ingresos por plan</th></tr>${byPlan.map(x=>`<tr><td>${x.plan}</td><td>${CLIENTS.filter(c=>c.plan===x.plan).length} cuentas</td><td>${money(x.total)}</td></tr>`).join('')}<tr class="accounting-total"><th>Total de ingresos</th><td></td><td>${money(revenue)}</td></tr><tr class="table-section"><th colspan="3">Costos y gastos</th></tr><tr><td>Costos directos de campañas</td><td></td><td>${money(direct)}</td></tr><tr><td>Incentivos a conductores</td><td>Flota registrada</td><td>${money(incentives)}</td></tr><tr><td>Gastos fijos de operación</td><td>Combustible · conectividad · mantenimiento</td><td>${money(fixed)}</td></tr><tr><td>Compras registradas este mes</td><td>${(state.expenses||[]).length} ${((state.expenses||[]).length)===1?'documento':'documentos'}</td><td>${money(expenses)}</td></tr><tr class="accounting-total"><th>Utilidad estimada</th><td></td><td>${money(profit)}</td></tr></tbody></table></div><div class="month-compare"><div><span>Mes actual</span><strong>${money(revenue)}</strong><small>Noviembre 2026</small></div><i>vs.</i><div><span>Mes anterior · comparativo de ejemplo</span><strong>${money(revenue/1.084)}</strong><small>Variación de referencia +8.4%</small></div></div></section>`}
function dgiView(){const filter=state.invoiceFilter||'Todas',month=state.invoiceMonth||'2026-11',records=CLIENTS.filter(c=>c.stage==='Activo').map((c,i)=>{const existing=state.invoices.find(x=>x.client===c.name);const status=existing?'Pendiente':i===1||i===3?'Autorizada por la DGI':i===5?'Anulada · nota de crédito':'Pendiente';return {client:c,number:`FV-2026-${String(441+i).padStart(4,'0')}`,amount:c.revenue,itbms:Math.round(c.revenue*.07*100)/100,cufe:existing?.cufe||`CUFE-EJ-${c.id.toUpperCase()}-2026`,status}}).filter(x=>month==='2026-11'&&(filter==='Todas'||x.status.startsWith(filter)));return `<section class="section-block dgi-section"><header class="section-heading"><div><span class="kicker">DOCUMENTOS FISCALES</span><h2>Facturación electrónica</h2></div><button class="button primary" data-action="invoice" data-id="c1">Emitir factura</button></header><div class="finance-filters"><label>Estado<select id="invoice-status-filter">${['Todas','Autorizada por la DGI','Pendiente','Anulada'].map(x=>`<option ${x===filter?'selected':''}>${x}</option>`).join('')}</select></label><label>Mes<input type="month" id="invoice-month-filter" value="${month}"></label><span>ITBMS de ejemplo · verificar tasa aplicable</span></div><div class="table-scroll"><table class="accounting-table dgi-table"><thead><tr><th>Número</th><th>Cliente</th><th>Monto</th><th>ITBMS</th><th>CUFE de ejemplo</th><th>Estado</th><th></th></tr></thead><tbody>${records.map(x=>`<tr><td>${x.number}</td><td>${esc(x.client.name)}</td><td>${money(x.amount)}</td><td>${money(x.itbms)}</td><td><code>${x.cufe}</code></td><td><span class="dgi-status ${x.status.startsWith('Autorizada')?'authorized':x.status.startsWith('Anulada')?'cancelled':'pending'}">${x.status}</span></td><td><button class="text-link" data-action="invoice-view" data-id="${x.client.id}">Ver ↗</button></td></tr>`).join('')}</tbody></table></div><p class="footnote">Los estados y CUFE son de ejemplo; la conexión de autorización no está activa.</p></section>`}
function expensesView(){const list=state.expenses||[],total=list.reduce((n,x)=>n+x.total,0),byCategory=expenseCategories.map(c=>({name:c,total:list.filter(x=>x.category===c).reduce((n,x)=>n+x.total,0)}));return `<section class="expense-upload section-block"><div class="expense-drop" id="expense-drop"><span class="brain-status"><i></i>Lectura de compras</span><h2>Arrastra una factura de compra</h2><p>Selecciona un archivo o prueba con un documento de ejemplo para revisar los datos antes de registrarlos.</p><label class="button outline">Seleccionar archivo<input id="expense-file" type="file" accept="image/*,.pdf" hidden></label><button class="button primary" data-action="expense-example">Probar con una factura de ejemplo</button><div id="expense-scan-result"></div></div></section><section class="section-block expense-ledger"><header class="section-heading"><div><span class="kicker">COMPRAS DEL MES</span><h2>Gastos y categorías</h2></div><strong>${money(total+3850)} <small>incluye gastos fijos</small></strong></header><div class="expense-bars">${byCategory.map(x=>`<div class="expense-bar-row"><span>${x.name}</span><i><b style="width:${total?Math.max(2,x.total/total*100):0}%"></b></i><strong>${money(x.total)}</strong></div>`).join('')}</div><div class="expense-list"><article><span>Gastos fijos de operación</span><small>Combustible · conectividad · mantenimiento</small><b>${money(3850)}</b></article>${list.map(x=>`<article><span>${esc(x.vendor)} · ${esc(x.category)}</span><small>${esc(x.date)} · Factura ${esc(x.number)}</small><b>${money(x.total)}</b></article>`).join('')||'<p class="empty-column">Todavía no se registran compras nuevas este mes.</p>'}</div></section>`}
function scanExpense(fileName='Factura de ejemplo.pdf'){const box=$('#expense-scan-result');if(!box)return;box.innerHTML=`<div class="ocr-reading"><i></i><span>Leyendo documento · ${esc(fileName)}</span></div>`;setTimeout(()=>{if(!$('#expense-scan-result'))return;const already=state.expenses?.some(x=>x.number==='FC-8931');box.innerHTML=`<form id="expense-form" class="expense-extracted"><span class="kicker">DATOS EXTRAÍDOS · REVISAR ANTES DE REGISTRAR</span><div class="expense-fields"><label>Proveedor<input name="vendor" value="Combustibles del Istmo, S.A." required></label><label>RUC<input name="ruc" value="1556123-1-2026 DV 04"></label><label>Fecha<input name="date" type="date" value="2026-11-12"></label><label>Número<input name="number" value="FC-8931" required></label><label>Subtotal<input name="subtotal" type="number" value="248.00" step=".01"></label><label>ITBMS<input name="itbms" type="number" value="17.36" step=".01"></label><label>Total<input name="total" type="number" value="265.36" step=".01"></label><label>Categoría sugerida<select name="category">${expenseCategories.map(x=>`<option ${x==='Combustible'?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="expense-alerts"><b>Alertas del cerebro</b><p>Este proveedor cobró 18% más que el mes pasado.</p><p>${already?'Factura registrada previamente.':'El gasto de combustible subió más que los kilómetros recorridos.'}</p><p>Verifica el número y el monto antes de guardar.</p></div><button class="button primary">Registrar gasto</button></form>`},850)}

function messages(){const all=[...(state.messages||[]),...(state.threads||[])].map(x=>({...x,kind:x.taskId?'task':'message'})).concat((state.questions||[]).filter(q=>[q.from,q.to].includes(profile().name)).map(x=>({...x,kind:'question'}))).sort((a,b)=>String(b.id).localeCompare(String(a.id)));const filter=state.messageFilter||'mine',visible=all.filter(m=>filter==='all'||(filter==='mine'?m.to===profile().name:m.from===profile().name));let active=visible.find(x=>x.id===state.selectedThread)||visible[0];if(active?.kind==='question'&&!(active.readBy||[]).includes(profile().name)){active.readBy=[...new Set([...(active.readBy||[]),profile().name])];save()}const filters=[['mine','Para mí'],['sent','Enviados'],['all','Todos']];return `<section class="messages-layout"><aside class="thread-list"><div class="section-heading"><div><span class="kicker">BANDEJA INTERNA</span><h2>Conversaciones</h2></div><button class="icon-btn" data-action="new-message" aria-label="Nuevo mensaje">＋</button></div><nav class="message-filters" aria-label="Filtrar mensajes">${filters.map(([id,label])=>`<button data-action="message-filter" data-value="${id}" class="${filter===id?'active':''}">${label}</button>`).join('')}</nav>${visible.length?visible.map(m=>`<button class="thread-item ${m.id===active?.id?'selected':''}" data-action="thread" data-id="${m.id}">${m.kind==='question'?`<span class="thread-module-icon">${moduleIcon(m.module)}</span>`:`<span class="thread-avatar">${esc(m.from.slice(0,1))}</span>`}<span><strong>${m.kind==='task'?'Tarea · ':''}${esc(m.subject.replace(/^Tarea · /,''))}</strong><small>${m.kind==='task'?'Tarea asignada · ':m.kind==='question'?`${esc(moduleNames[m.module]||m.module)} · `:''}${esc(m.kind==='question'?m.time:m.ref+' · '+m.time)}</small><p>${esc(m.body)}</p></span></button>`).join(''):'<p class="empty-column">No hay conversaciones en este filtro.</p>'}</aside><section class="conversation">${active?`<div class="conversation-head"><div><span class="kicker">HILO INTERNO</span><h2>${esc(active.subject)}</h2></div><span class="linked-record">${active.kind==='question'?`Para ${esc(active.to)}`:`Vinculado a ${esc(active.ref)}`}</span></div>${active.kind==='question'?`<article class="asked-data-card thread-data-card"><span class="kicker">${esc(moduleNames[active.module]||active.module)}</span><strong>${esc(active.name.replace('Zona · ',''))}</strong><p>${esc(active.value)} · ${esc(active.period)}</p><button class="button outline small" data-action="question-view-data" data-id="${active.id}">Ver el dato</button></article><div class="message-bubble"><small>${esc(active.from)} · ${esc(active.time)}</small><p>${esc(active.body)}</p></div>${(active.replies||[]).map(reply=>`<div class="message-bubble reply-bubble"><small>${esc(reply.from)} · ${esc(reply.time)}</small><p>${esc(reply.body)}</p></div>`).join('')}<form id="question-reply-form" class="message-compose"><label for="question-reply">RESPONDER A ${esc(active.from===profile().name?active.to:active.from).toUpperCase()}</label><textarea id="question-reply" name="body" placeholder="Escribe tu respuesta" required></textarea><button class="button primary">Enviar respuesta</button></form>`:`<div class="message-bubble"><small>${esc(active.from)} · ${esc(active.time)}</small><p>${esc(active.body)}</p><span class="linked-record">Registro · ${esc(active.ref)}</span>${active.taskId&&!(state.tasks||[]).find(t=>t.id===active.taskId)?.done&&active.to===profile().name?`<button class="button primary small task-done-button" data-action="task-done" data-id="${active.taskId}">Marcar como hecha</button>`:''}</div><form id="message-form" class="message-compose"><label for="message-input">RESPONDER AL HILO</label><textarea id="message-input" placeholder="Escribe un mensaje para tu equipo" required></textarea><div><label class="field-label">VINCULAR A<select id="message-ref">${['Clínica Sonrisa','Tropigas','Combustible · noviembre','McDonald’s','Pantalla MA-07'].map(x=>`<option>${x}</option>`).join('')}</select></label><button class="button primary">Enviar mensaje</button></div></form>`}`:`<div class="conversation-empty"><h2>Pregunta sobre una cifra</h2><p>Las consultas que envíes o recibas aparecerán aquí con el dato y su responsable.</p></div>`}</section></section>`}

function team(){return `<section class="team-intro"><div><span class="kicker">CONTROL DE ACCESO</span><h2>Roles y datos protegidos</h2><p>Los permisos determinan qué puede consultar y cambiar cada usuario. Cada persona personaliza su pantalla y su agente; los socios deciden los permisos.</p></div><button class="button primary" data-action="add-user">Agregar usuario +</button></section><section class="section-block permissions"><div class="section-heading"><div><span class="kicker">MATRIZ DE PERMISOS</span><h2>Rol contra permiso</h2></div><span class="quiet-note">Los socios tienen acceso total</span></div><div class="table-scroll"><table class="permission-table"><thead><tr><th>PERMISO</th>${allProfiles().map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${USER_CONFIG.permissionRows.map(([name,desc,key])=>`<tr><th>${name}<small>${desc}</small></th>${allProfiles().map(p=>{let yes=p.access==='owner'||(key==='ver')||(key==='editar'&&['sales','finance'].includes(p.access))||(key==='exportar'&&p.access==='owner');return `<td><span class="permission ${yes?'yes':'no'}">${yes?'✓':'×'}</span></td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="permission-cards">${allProfiles().map(p=>`<article><header><strong>${esc(p.name)}</strong><small>${esc(p.role)}</small></header>${USER_CONFIG.permissionRows.map(([name,desc,key])=>{const yes=p.access==='owner'||key==='ver'||(key==='editar'&&['sales','finance'].includes(p.access))||(key==='exportar'&&p.access==='owner');return `<div class="permission-card-row"><span>${name}</span><b class="${yes?'yes':'no'}">${yes?'Permitido':'Sin acceso'}</b></div>`}).join('')}</article>`).join('')}</div></section><section class="section-block user-list"><div class="section-heading"><div><span class="kicker">USUARIOS ACTIVOS</span><h2>Personas con acceso</h2></div></div>${allProfiles().map(p=>`<div class="user-row"><span class="user-avatar">${p.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.role)} · ${esc(p.autonomy)}</small></div><span class="user-state">Activo</span><button class="text-link" data-action="user-access" data-id="${p.id}">Permisos ↗</button></div>`).join('')}</section><section class="export-panel"><div><span class="kicker light">PORTABILIDAD</span><h2>Tus datos son tuyos</h2><p>Descarga un archivo con los datos de ejemplo y los cambios que hiciste en esta sesión.</p></div><button class="button light-button" data-action="export-all" ${canExport()?'':'disabled'}>Exportar todos mis datos ↓</button></section>`}

function connections(){return `<section class="connections-intro"><span class="kicker">SERVICIOS Y SISTEMAS</span><h2>Un espacio para la operación</h2><p>Estado de los servicios y conexiones de MOVIADS. Conectar estos servicios requiere configuración y credenciales de MOVIADS.</p></section><section class="connection-list">${INTEGRATIONS.map((i,n)=>`<article class="connection-row"><div class="connection-mark">${['G','W','O','D'][n]}</div><div class="connection-name"><strong>${esc(i.name)}</strong><small>${esc(i.sub)}</small></div><div class="connection-state"><span class="state-bar ${n===2||n===3?'demo':''}"></span><strong>${esc(state.sync[i.name]||i.state)}</strong><small>Última actividad · ${esc(i.last)}</small></div><button class="button ${n===2||n===3?'quiet':'outline'} small" data-action="integration" data-name="${esc(i.name)}">${n===2||n===3?'Ver detalles':'Conectar'}</button></article>`).join('')}</section><section class="section-block integration-notes"><div><span class="kicker">GOOGLE WORKSPACE</span><p>Gmail, Calendar, Meet y Drive aparecen juntos para apoyar correos, reuniones y archivos asociados al cliente.</p></div><div><span class="kicker">ONSIGN</span><p>Las pautas se prepararían en MOVIADS Central y se enviarían al sistema de pantallas tras validar la conexión disponible.</p></div><div><span class="kicker">FACTURA DGI</span><p>La vista de factura representa el documento fiscal con folio, CUFE y QR; la autorización real no está conectada.</p></div></section>`}

function saleModal(){openModal('Simular venta',`<p class="modal-intro">Al confirmar, el sistema reserva un espacio por pantalla del plan para el período seleccionado.</p><form id="sale-form" class="form-grid"><label class="field-label span-two">CLIENTE<select name="client" required>${CLIENTS.map(c=>`<option>${esc(c.name)}</option>`).join('')}<option>Nuevo cliente de ejemplo</option></select></label><label class="field-label">PLAN<select name="plan">${PLANS.map(p=>`<option value="${p.id}">${p.id} · ${p.screens} ${p.screens===1?'pantalla':'pantallas'}</option>`).join('')}</select></label><label class="field-label">MES<input name="month" type="month" value="${state.month}" required></label><label class="field-label">FECHA DE INICIO<input name="start" type="date" value="${state.month}-01"></label><label class="field-label">FECHA DE CIERRE<input name="end" type="date" value="${state.month}-${new Date(Number(state.month.slice(0,4)),Number(state.month.slice(5,7)),0).getDate()}"></label><label class="field-label">INVERSIÓN DE EJEMPLO<input name="value" type="number" min="0" step="50" value="3200"></label><div class="form-submit span-two"><span>Disponibles en el período: <b id="sale-availability">elige un plan</b></span><button class="button primary">Confirmar venta simulada</button></div></form>`)}
function demoCampaigns(){return [...CLIENTS.filter(c=>c.stage==='Activo').map((c,i)=>({id:`PA-${String(i+21).padStart(3,'0')}`,client:c.name,creative:c.creative,plays:c.plays,target:c.target,plan:c.plan,sync:state.sync[`PA-${String(i+21).padStart(3,'0')}`]||(i===2?'Pendiente de envío':'Sincronizado'),zone:c.zones[0]})),...state.campaigns.map(c=>({...c,sync:state.sync[c.id]||c.sync}))]}
function pautaModal(id){const c=demoCampaigns().find(x=>x.id===id);if(!c)return;const plan=PLANS.find(p=>p.id===c.plan)||{screens:1};const n=plan.screens||1;const franjas=[['6 a 9 a. m.',38],['9 a 12 m.',57],['12 a 3 p. m.',68],['3 a 6 p. m.',91],['6 a 9 p. m.',73]];const tot=franjas.reduce((s,f)=>s+f[1],0);const target=Number(c.target)||0;const porPantalla=Math.round(target/n);const pesos=Array.from({length:n},(_,i)=>1+0.16*Math.sin(i*1.7+0.4));const sp=pesos.reduce((s,x)=>s+x,0);const fila=k=>{const base=target*pesos[k]/sp;return franjas.map(f=>Math.round(base*f[1]/tot))};const zonas=['Paitilla','Obarrio','Calle 50','Costa del Este','San Francisco','Vía España','El Cangrejo','Bella Vista','Albrook','Juan Díaz','Condado del Rey','Marbella','Punta Pacífica','Tumba Muerto','San Miguelito','Vía Israel','Brisas del Golf'];const filas=Array.from({length:n},(_,i)=>{const v=fila(i);return `<tr><th>MA-${String(i+1).padStart(2,'0')}<small>${esc(zonas[i%zonas.length])}</small></th>${v.map(x=>`<td>${num(x)}</td>`).join('')}<td><b>${num(v.reduce((s,x)=>s+x,0))}</b></td></tr>`}).join('');const ok=c.sync==='Sincronizado';openModal(`Pauta ${c.id} · ${c.client}`,`<p class="modal-intro">El sistema reparte las ${num(target)} reproducciones contratadas entre las ${n} pantallas del plan ${esc(c.plan)} y las cinco franjas de operación, con más peso en las horas de mayor tráfico.</p><div class="pauta-stats"><div><span>Creativo</span><b>${esc(c.creative||'Pendiente')}</b></div><div><span>Entregadas</span><b>${num(c.plays||0)} de ${num(target)}</b></div><div><span>Por pantalla</span><b>${num(porPantalla)}</b></div><div><span>OnSign</span><b>${ok?'Sincronizada':'Pendiente de envío'}</b></div></div><div class="pauta-table-wrap"><table class="pauta-table"><thead><tr><th>Pantalla</th>${franjas.map(f=>`<th>${f[0]}</th>`).join('')}<th>Total</th></tr></thead><tbody>${filas}</tbody></table></div><div class="form-submit"><span>${ok?'La distribución ya está en OnSign. Cualquier cambio se vuelve a enviar con un clic.':'Revisa la distribución y envíala a OnSign.'}</span>${ok?'<button class="button outline" data-action="close-modal">Cerrar</button>':`<button class="button primary" data-action="sync-modal" data-id="${esc(c.id)}">Enviar a OnSign</button>`}</div>`,true)}
function campaignModal(){openModal('Crear pauta',`<p class="modal-intro">Registra lo contratado y prepara una distribución por pantalla y hora.</p><form id="campaign-form" class="form-grid"><label class="field-label span-two">CLIENTE<select name="client">${CLIENTS.map(c=>`<option ${c.name==='Bambito'?'selected':''}>${esc(c.name)}</option>`).join('')}<option>Nuevo cliente de ejemplo</option></select></label><label class="field-label">CREATIVO<input name="creative" value="campana-diciembre.mp4" required></label><label class="field-label">PLAN<select name="plan">${PLANS.map(p=>`<option value="${p.id}">${p.id} · ${p.screens} ${p.screens===1?'pantalla':'pantallas'}</option>`).join('')}</select></label><label class="field-label">REPRODUCCIONES CONTRATADAS<input name="target" type="number" min="100" value="45000" required></label><label class="field-label">FECHA DE INICIO<input name="start" type="date" value="${monthValue()}-01"></label><label class="field-label">FECHA DE CIERRE<input name="end" type="date" value="${monthValue()}-30"></label><label class="field-label">ZONA PREFERIDA<select name="zone">${ZONES.map(z=>`<option>${z}</option>`).join('')}</select></label><label class="field-label">HORARIO<select name="hours"><option>Todo el día</option><option>6 a. m. a 12 p. m.</option><option>12 p. m. a 6 p. m.</option><option>3 p. m. a 9 p. m.</option></select></label><div class="form-submit span-two"><span>Distribución calculada al guardar · Conexión OnSign de ejemplo</span><button class="button primary">Crear y distribuir pauta</button></div></form>`)}
function clientModal(id){const c=CLIENTS.find(x=>x.id===id);if(!c)return;openModal(c.name,`<div class="client-detail-head"><div><span class="kicker">${esc(c.stage.toUpperCase())} · ${esc(c.plan)}</span><h3>${esc(c.contact)}</h3><p>${esc(c.email)} · ${esc(c.phone)}</p></div><button class="button outline" data-action="new-message" data-ref="${esc(c.name)}">Escribir al equipo</button></div><div class="detail-stat-grid"><div><span>Tiempo pautando</span><strong>${c.stage==='Activo'?'Campaña mensual':'Sin pauta activa'}</strong></div><div><span>Pagado en noviembre</span><strong>${profile().access==='service'?'Sin acceso':money(c.stage==='Activo'?c.revenue*.82:0)}</strong></div><div><span>Campaña actual</span><strong>${esc(c.campaign||'No aplica')}</strong></div><div><span>Creativo</span><strong>${esc(c.creative||'Pendiente')}</strong></div></div><div class="detail-two"><section><span class="kicker">CAMPAÑAS</span><div class="timeline-record"><b>${esc(c.campaign||'Registro comercial')}</b><small>${esc(c.period||'En preparación')} · ${esc(c.plan)} · ${num(c.plays)} reproducciones</small></div><div class="timeline-record"><b>Historial</b><small>${esc(c.history)} · ${money(c.revenue)} registrados</small></div><span class="kicker">LLAMADAS Y MENSAJES</span><div class="timeline-record"><b>Resumen de llamada · 6 nov</b><small>Conversaron sobre cobertura por zona, duración de pauta y medición del QR.</small></div><details class="transcript-details"><summary>Ver transcripción de llamada</summary><p><b>${esc(c.contact)}:</b> Queremos priorizar las zonas cercanas a nuestras sucursales y entender cuántas personas llegan desde el QR.</p><p><b>MOVIADS:</b> Podemos documentar reproducciones por equipo y presentar los escaneos y acciones del QR en el reporte mensual.</p></details><div class="timeline-record"><b>Correo · 12 nov</b><small>${esc(c.contact)} solicita el resumen de cobertura y el creativo aprobado.</small></div><div class="timeline-record"><b>WhatsApp · ${esc(c.contact)}</b><small>Cliente solicita revisar resultados al cierre de mes. ${c.messages} mensajes vinculados.</small></div><div class="timeline-record"><b>Factura vinculada</b><small>${c.stage==='Activo'?`FV-2026-${String(CLIENTS.indexOf(c)+441).padStart(4,'0')} · ${money(c.revenue)}`:'Sin factura activa'}</small></div><div class="client-detail-actions">${c.stage==='Activo'?`<button class="text-link" data-action="invoice" data-id="${c.id}">Abrir factura ↗</button>`:''}<button class="text-link" data-action="thread-ref" data-ref="${esc(c.name)}">Abrir mensajes internos ↗</button></div></section><aside class="client-detail-side"><span class="kicker">MEDICIÓN</span><strong>${num(c.plays)}</strong><small>reproducciones entregadas</small><div class="progress-line"><i style="width:${c.target?Math.min(100,c.plays/c.target*100):0}%"></i></div><div class="side-metric"><span>Escaneos QR</span><b>${num(c.scans)}</b></div><div class="side-metric"><span>Acciones</span><b>${num(c.actions)}</b></div><div class="side-metric"><span>Factura</span><b>${money(c.revenue)}</b></div><button class="button primary full" data-action="report" data-client="${esc(c.name)}">Generar reporte</button><button class="button outline full" data-action="client-portal" data-id="${c.id}">Así lo ve tu cliente ↗</button></aside></div>` ,true)}
function leadModal(id){const l=LEADS.find(x=>x.id===id);if(!l)return;openModal(l.name,`<div class="lead-detail-title"><div><span class="kicker">${esc(l.sector)} · ${esc(l.zone)}</span><h3>${esc(l.person)}</h3></div><span class="lead-heat">${esc(state.leadHeat[l.id]||l.heat)}</span></div><div class="lead-conversation">${l.messages.map((m,i)=>`<div class="chat-message ${i%2?'incoming':''}"><small>${i%2?esc(l.name):'MOVIADS Central'}</small><p>${esc(m.split(': ').slice(1).join(': '))}</p></div>`).join('')}</div><div class="lead-brief"><div><span>Qué busca</span><strong>${esc(l.intent)}</strong></div><div><span>Segundos</span><strong>${l.seconds||'Por definir'}</strong></div><div><span>Zonas</span><strong>${esc(l.zone)}</strong></div><div><span>Presupuesto</span><strong>${l.budget?money(l.budget):'Por conversar'}</strong></div></div><div class="lead-modal-actions"><button class="button outline" data-action="new-message" data-ref="${esc(l.name)}">Consultar al equipo</button>${!isAutonomous()||agentConfig().clients.includes(l.name)?`<button class="button primary" data-action="approve-lead" data-id="${l.id}">Aprobar próximo mensaje</button>`:`<button class="button primary" data-action="approve-lead" data-id="${l.id}">Ver próximo paso</button>`}</div>`)}
function unitModal(id){const f=FLEET.find(x=>x.id===id);if(!f)return;openModal(`Unidad ${f.id}`,`<div class="unit-detail"><img src="./assets/${f.image}" alt="Vehículo de flota"><div><span class="kicker">${esc(f.car)}</span><h3>${esc(f.driver)}</h3><div class="screen-state ${f.status}"><i></i>${f.status==='online'?'Pantalla encendida':f.status==='off'?'Pantalla apagada':'Sin señal'}</div></div></div><div class="detail-stat-grid"><div><span>Horas activas hoy</span><strong>${f.hours.toFixed(1)} h</strong></div><div><span>Kilómetros registrados</span><strong>${num(f.km)} km</strong></div><div><span>Zona reciente</span><strong>${esc(f.zone)}</strong></div>${profile().access==='service'?'':`<div><span>Incentivo mensual</span><strong>${money(f.incentive)}</strong></div>`}</div><div class="timeline-record"><b>Comportamiento del conductor</b><small>${esc(f.behavior)} · Métrica ilustrativa según recorridos registrados.</small></div>${profile().access==='service'?'':`<button class="button outline" data-action="ask-accountant" data-amount="Incentivo ${f.driver} · ${money(f.incentive)}">Preguntar ↗</button>`}`)}
function reportModal(name){const c=CLIENTS.find(x=>x.name===name)||CLIENTS[0];openModal(`Reporte de ${c.name}`,`<div class="report-preview" id="report-print"><header><img src="./assets/logo-moviads.svg" alt="MOVIADS"><span>REPORTE DE CAMPAÑA · NOVIEMBRE 2026</span></header><h3>${esc(c.name)}</h3><p>${esc(c.campaign||'Resumen de actividad')} · ${esc(c.period||'Noviembre 2026')}</p><div class="report-kpis"><div><strong>${num(c.plays)}</strong><span>reproducciones</span></div><div><strong>${num(c.scans)}</strong><span>escaneos QR</span></div><div><strong>${num(c.actions)}</strong><span>acciones</span></div><div><strong>${c.zones.length}</strong><span>zonas cubiertas</span></div></div><div class="report-map"><svg viewBox="0 0 800 180"><path d="M18 137 C142 110 195 120 283 82 S424 110 510 58 S675 73 783 22" fill="none" stroke="#173A7A" stroke-width="3"/>${c.zones.map((z,i)=>`<circle cx="${40+i*95}" cy="${130-(i%3)*38}" r="5" fill="#15A595"/><text x="${40+i*95}" y="${154-(i%3)*38}" font-size="11" fill="#4F5867">${esc(z)}</text>`).join('')}</svg></div><div class="report-foot"><span>Comparativo mensual</span><strong>+8.4% reproducciones frente a octubre</strong><small>Registro de fecha, hora, equipo y coordenada GPS disponible para auditoría.</small></div></div><div class="modal-actions"><button class="button outline" data-action="report-csv" data-client="${esc(c.name)}">Descargar Excel · CSV</button><button class="button primary" data-action="print-report">Imprimir / guardar PDF</button></div>` ,true)}
function invoiceModal(c){const numId=`FV-2026-${String(CLIENTS.indexOf(c)+441).padStart(4,'0')}`;const generated=state.invoices.find(x=>x.client===c.name);const ref=generated?.cufe||'CUFE-DMO-26-0000-0000-0000-0000';openModal(`Factura · ${c.name}`,`<div class="invoice-document" id="invoice-print"><header><img src="./assets/logo-moviads.svg" alt="MOVIADS"><div><b>FACTURA ELECTRÓNICA</b><span>MOVIADS · DOCUMENTO</span></div></header><div class="invoice-doc-id"><span>${numId}</span><span>Fecha de emisión · 18 nov 2026</span></div><div class="invoice-billto"><span>FACTURAR A</span><strong>${esc(c.name)}</strong><small>${esc(c.contact)} · Panamá</small></div><div class="invoice-line"><span>Campaña de publicidad digital exterior · ${esc(c.plan)}</span><strong>${money(c.revenue)}</strong></div><div class="invoice-total"><span>Total USD</span><strong>${money(c.revenue)}</strong></div><div class="cufe-block"><div><span>CUFE</span><b>${ref}</b><small>No válido para trámite fiscal</small></div><div class="qr-fake" aria-label="Código QR ilustrativo">${Array.from({length:64},(_,i)=>`<i style="opacity:${(i*11%7)/8+.12}"></i>`).join('')}</div></div></div><div class="modal-actions"><button class="button outline" data-action="print-invoice">Imprimir / guardar PDF</button><button class="button primary" data-action="invoice-done" data-id="${c.id}">${generated?'Listo':'Marcar como emitida'}</button></div><p class="footnote">Representación ilustrativa. No está autorizada por la DGI.</p>`)}
