 if(/ingreso|venta|vend|factur|ventas|facturamos|vendimos/.test(s)){return {value:money(month.revenue),context:`Ingresos registrados en ${monthName(month.month)}; ${num(month.spacesSold)} espacios vendidos y ${num(month.plays)} reproducciones.`,chart:[historyMonth('2026-10').revenue,month.revenue],period:monthName(month.month),target:'finanzas'};}
 if(/debe|deuda|saldo|pendiente|no pago|no ha pagado|por cobrar/.test(s)){if(client){const paid=['McDonald’s','Cochez','Nexa Solutions'].includes(client.name);return {value:paid?money(0):money(client.revenue),context:paid?`${client.name} aparece pagado en noviembre.`:`${client.name} tiene factura pendiente por ${money(client.revenue)} en noviembre.`,period:'noviembre 2026',target:'finanzas'};}const debt=CLIENTS.filter(c=>c.stage==='Activo'&&!['McDonald’s','Cochez','Nexa Solutions'].includes(c.name)).reduce((a,c)=>a+c.revenue,0);return {value:money(debt),context:'4 documentos aparecen pendientes. Abre Finanzas para revisar cada vencimiento.',period:'noviembre 2026',target:'finanzas'};}
 if(/renov|renueva|vencer|proximo a/.test(s)){const renew=CLIENTS.filter(c=>c.stage==='Activo'&&c.history.includes('Renovación'));return {value:renew[0]?.name||'Tropigas',context:'La renovación mensual figura para el 30 de noviembre. Eric es el socio responsable.',period:'noviembre 2026',target:'clientes'};}
 if(/mejor cliente|mas pago|mayor cliente|cliente que mas/.test(s)){const c=[...CLIENTS].sort((a,b)=>b.revenue-a.revenue)[0];return {value:c.name,context:`Registra ${money(c.revenue)} en noviembre, el monto más alto entre los clientes activos.`,period:'noviembre 2026',target:'clientes'};}
 if(/reprodu|escaneo|qr|zona|hora/.test(s)){if(/mejor hora|hora con mas|horario con mas/.test(s))return {value:'3 a 6 p. m.',context:'La programación asigna el mayor peso a esa franja (91 puntos). No hay desglose de escaneos por hora en el registro disponible.',period:monthName(month.month),target:'medicion'};if(client&&/cliente|tropigas|mcdonald|novey|cochez|denago|nexa|wheelz/.test(s))return {value:/escaneo|qr/.test(s)?num(client.scans):num(client.plays),context:`${/escaneo|qr/.test(s)?'Escaneos QR':'Reproducciones'} de ${client.name} en noviembre; la campaña cubre ${client.zones.join(', ')}.`,chart:[client.scans,client.actions],period:'noviembre 2026',target:'medicion'};const zoneTotals={};CLIENTS.filter(c=>c.stage==='Activo').forEach(c=>c.zones.forEach(z=>zoneTotals[z]=(zoneTotals[z]||0)+((/escaneo|qr/.test(s)?c.scans:c.plays)/c.zones.length)*(month.scans/historyMonth('2026-11').scans)));const best=Object.entries(zoneTotals).sort((a,b)=>b[1]-a[1])[0],requestedZone=Object.keys(zoneTotals).find(z=>s.includes(normalizeText(z)));if(requestedZone){const amount=zoneTotals[requestedZone];return {value:num(Math.round(amount)),context:`${/escaneo|qr/.test(s)?'Escaneos QR':'Reproducciones'} estimados para ${requestedZone}, distribuidos entre las zonas de cobertura de las campañas activas.`,period:'noviembre 2026',target:'medicion'};}if(/mejor zona|mas escaneo|mas reprodu/.test(s))return {value:best[0],context:`Registra ${num(Math.round(best[1]))} ${/escaneo|qr/.test(s)?'escaneos QR':'reproducciones'} estimados en noviembre, según la distribución de las campañas activas.`,chart:[best[1],Math.round(best[1]*.78)],period:'noviembre 2026',target:'medicion'};return {value:num(month.scans),context:`Escaneos registrados en ${monthName(month.month)}. La zona con más respuesta es ${best[0]} (${num(best[1])} escaneos).`,chart:[month.scans,historyMonth('2026-10').scans],period:monthName(month.month),target:'medicion'};}
