 if(/pantalla|senal|apagada|unidad|recorrido|conductor|horas/.test(s)){if(/recorrido|kilomet|mas recorrido/.test(s)){const f=[...FLEET].sort((a,b)=>b.km-a.km)[0];return {value:f.id,context:`${f.driver} registra ${num(f.km)} km y su zona reciente es ${f.zone}.`,period:'noviembre 2026',target:'flota'};}if(/conductor|horas/.test(s)){const f=[...FLEET].sort((a,b)=>b.hours-a.hours)[0];return {value:f.driver,context:`Lleva ${f.hours.toFixed(1)} horas activas hoy en la unidad ${f.id}.`,period:'hoy',target:'flota'};}const off=FLEET.filter(f=>f.status!=='online');return {value:`${off.length} unidades por revisar`,context:`${off.filter(f=>f.status==='off').length} pantalla apagada y ${off.filter(f=>f.status==='offline').length} unidad sin señal reciente.`,period:'hoy',target:'flota'};}
 if(/lead|prospect|caliente|semana|origen|vienen/.test(s)){const hot=LEADS.filter(l=>(state.leadHeat?.[l.id]||l.heat)==='Caliente'),week=LEADS.filter(l=>/hoy|ayer/.test(normalizeText(l.last))),top=hot[0];return {value:/origen|vienen|canal/.test(s)?'WhatsApp y correo':`${week.length} leads esta semana`,context:`${hot.length} aparecen calientes. ${top?.name||'Clínica Sonrisa'} es una oportunidad prioritaria.`,period:'esta semana',target:'agentes'};}
