 if(/hoy|recom|que hago|donde esta/.test(s)){const open=Object.keys(state.decisions||{}).length;return {value:'Revisa cobros y la señal de MA-07',context:`Hay ${num(pendingReceivable())} por cobrar, ${LEADS.filter(l=>(state.leadHeat?.[l.id]||l.heat)==='Caliente').length} leads calientes y 2 alertas de flota. El cerebro de cada área incluye recomendaciones.`,period:'noviembre 2026',target:'inicio'};}
