function start(){const params=new URLSearchParams(location.search),host=location.hostname;const local=['localhost','127.0.0.1','::1'].includes(host);const cap=local&&params.get('cap');if(cap){const v=MODULES.find(x=>x[0]===cap||x[1].toLowerCase()===cap.toLowerCase());if(v)state.view=v[0];const who=allProfiles().find(p=>p.id===params.get('perfil'));if(who)state.profile=who.id;sessionStorage.setItem('moviads-auth','yes');save();render();return;}if(sessionStorage.getItem('moviads-auth')==='yes'){render();return;}showGate();}

