document.addEventListener('keydown',e=>{if(e.target.id==='command-input'&&e.key==='Enter'){e.preventDefault();$('.command-results button:not([hidden])')?.click();return;}if(e.target.id==='command-input'&&(e.key==='ArrowDown'||e.key==='ArrowUp')){e.preventDefault();const list=$$('.command-results button:not([hidden])'),i=list.indexOf(document.activeElement),n=(i+(e.key==='ArrowDown'?1:-1)+list.length)%list.length;list[n]?.focus();return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();assistantModal();}if(e.key==='Escape'){if(document.body.classList.contains('portal-open')){document.body.classList.remove('portal-open');clearInterval(portalInterval);portalInterval=0;}closeModal();}});
